package has_close_elements_test

import (
	"math"
	"sort"
)

// Check if in given list of numbers, are any two numbers closer to each other than
// given threshold.
// >>> has_close_elements([]float64{1.0, 2.0, 3.0}, 0.5)
// false
// >>> has_close_elements([]float64{1.0, 2.8, 3.0, 4.0, 5.0, 2.0}, 0.3)
// true
func has_close_elements(numbers []float64, threshold float64) bool {
	if len(numbers) < 2 {
		return false
	}

	// Sort the numbers to easily check adjacent elements
	sortedNumbers := make([]float64, len(numbers))
	copy(sortedNumbers, numbers)
	sort.Float64s(sortedNumbers)

	// Check the difference between adjacent elements
	for i := 0; i < len(sortedNumbers)-1; i++ {
		diff := math.Abs(sortedNumbers[i+1] - sortedNumbers[i])
		if diff < threshold {
			return true
		}
	}

	return false
}
