func find_closest_elements(numbers []float64) []interface{} {
	if len(numbers) < 2 {
		return nil // Should not happen based on problem description, but good practice
	}

	// Sort the numbers first. This ensures that the closest elements will be adjacent after sorting.
	// We use a simple bubble sort or similar logic if we want to avoid importing "sort",
	// but since we are in a test file context, using the standard library sort is appropriate
	// for efficiency and correctness.
	// However, to keep dependencies minimal and self-contained if this were a library function,
	// we can iterate through all pairs, which is O(n^2). Since the prompt implies a standard
	// implementation, sorting (O(n log n)) is the standard approach.

	// Let's use a copy and sort it to avoid modifying the input slice.
	sortedNumbers := make([]float64, len(numbers))
	copy(sortedNumbers, numbers)

	// Simple bubble sort implementation for demonstration if we cannot import "sort"
	// If imports are allowed, we would use sort.Float64s(sortedNumbers)
	for i := 0; i < len(sortedNumbers); i++ {
		for j := 0; j < len(sortedNumbers)-i-1; j++ {
			if sortedNumbers[j] > sortedNumbers[j+1] {
				sortedNumbers[j], sortedNumbers[j+1] = sortedNumbers[j+1], sortedNumbers[j]
			}
		}
	}

	minDiff := math.MaxFloat64
	var closestA, closestB float64

	// Iterate through the sorted array and check adjacent elements
	for i := 0; i < len(sortedNumbers)-1; i++ {
