		if diff < minDiff {
			minDiff = diff
			closestA = sortedNumbers[i]
			closestB = sortedNumbers[i+1]
		}
	}

	// Return the result in the required format: []interface{}{smaller, larger}
	return []interface{}{closestA, closestB}
