// >>> correct_bracketing("<")
// false
// >>> correct_bracketing("<>")
// true
// >>> correct_bracketing("<<><>>")
// true
// >>> correct_bracketing("><<>")
// false
func correct_bracketing(brackets string) bool {
	count := 0
	for _, char := range brackets {
		if char == '<' {
			count++
		} else if char == '>' {
			count--
		}
		// If count drops below zero, it means a closing bracket appeared without a corresponding opening bracket
		if count < 0 {
			return false
		}
	}
	// For the brackets to be correct, the final count must be zero
	return count == 0
}
