package is_simple_power_test

import (
	"math"
)

// is_simple_power returns true if x is a simple power of n (n^int = x) and false otherwise.
// The exponent 'int' must be an integer greater than 1 based on the examples provided.
func is_simple_power(x int, n int) bool {
	// Handle edge cases based on typical power function constraints and examples.

	// If n is 1, x must be 1 for any positive integer power.
	if n == 1 {
		return x == 1
	}

	// If n is 0, x must be 0 (for power > 1) or 1 (for power 0, but we assume power > 1).
	if n == 0 {
		return x == 0 && x != 1 // 0^p = 0 for p > 0. If x=1, it's 0^0 which is often undefined or 1.
	}

	// If x is 1, it is n^0. Since the examples imply the exponent must be > 1,
	// we return false unless n itself is 1 (handled above).
	if x == 1 {
		return false
	}

	// If x is negative, n must also be negative for an integer power to result in a negative x,
	// unless the exponent is 0 (which we excluded).
	if x < 0 && n > 0 {
		return false
	}

	// If n is negative, we check if x is reachable.
	if n < 0 {
		// If x is positive, n^p can only be positive if p is even.
		if x > 0 {
			// Check if x is a power of |n| with an even exponent.
			absN := -n
			return isPower(x, absN) && (math.Log2(float64(x))/math.Log2(float64(absN)) == math.Floor(math.Log2(float64(x))/math.Log2(float64(absN))))
		}
		// If x is negative, n^p is negative if p is odd.
		if x < 0 {
			absX := -x
			absN := -n
			// Check if |x| is a power of |n|.
			return isPower(absX, absN) && (math.Log2(float64(absX))/math.Log2(float64(absN)) == math.Floor(math.Log2(float64(absX))/math.Log2(float64(absN))))
		}
	}

	// General case: n > 1 and x > 1
	return isPower(x, n)
}

// isPower checks if x is an integer power of base n (n^p = x, p >= 1).
// This helper function assumes base >= 2 and x >= 1.
func isPower(x int, base int) bool {
	if base < 2 || x < 1 {
		return false
	}
	if x == 1 {
		// If x is 1, it's base^0, but we are looking for p >= 1 based on examples.
		return false
	}

	current := base
	for current < x {
		// Check for potential overflow before multiplication
		if math.MaxInt/base < current {
			return false // Next multiplication would overflow
		}
		current *= base
	}

	return current == x
}
