// "1"
// >>> solve(150)
// "110"
// >>> solve(147)
// "1100"
// Variables:
// @N integer
// Constraints: 0 ≤ N ≤ 10000.
// Output:
// a string of binary number
func solve(N int) string {
	if N == 0 {
		return "0"
	}
	binary := ""
	for N > 0 {
		remainder := N % 2
		if remainder == 1 {
			binary = "1" + binary
		} else {
			binary = "0" + binary
		}
		N = N / 2
	}
	return binary
