// Given a list of non-negative integers, return a cogo of the given list after sorting,
// you will sort the given list in ascending order if the sum( first index value, last index value) is odd,
// or sort it in descending order if the sum( first index value, last index value) is even.
// Note:
// * don't change the given list.
// Examples:
// >>> sort_array([]int{})
// []int{}
// >>> sort_array([]int{5})
// []int{5}
// >>> sort_array([]int{2, 4, 3, 0, 1, 5})
// []int{0, 1, 2, 3, 4, 5}
// >>> sort_array([]int{2, 4, 3, 0, 1, 5, 6})
// []int{6, 5, 4, 3, 2, 1, 0}
func sort_array(array []int) []int {
	n := len(array)
	if n <= 1 {
		// Return a copy to adhere to "don't change the given list"
		result := make([]int, n)
		copy(result, array)
		return result
	}

	first := array[0]
	last := array[n-1]
	sum := first + last

	// Create a copy of the input array to avoid modifying the original
	sortedArray := make([]int, n)
	copy(sortedArray, array)

	if sum%2 != 0 {
		// Odd sum: sort in ascending order
		sort.Ints(sortedArray)
	} else {
		// Even sum: sort in descending order
		sort.Sort(sort.Reverse(sort.IntSlice(sortedArray)))
	}

	return sortedArray
}
