// count_up_to takes a non-negative integer n and returns a list of the first n
// integers that are prime numbers and less than n.
// Note: The examples suggest the function should return all primes strictly less than n,
// not the first n primes.
func count_up_to(n int) []int {
	if n <= 2 {
		return []int{}
	}

	// Sieve of Eratosthenes to find all primes up to n-1
	isPrime := make([]bool, n)
	for i := 2; i < n; i++ {
		isPrime[i] = true
	}

	for p := 2; p*p < n; p++ {
		if isPrime[p] {
			for i := p * p; i < n; i += p {
				isPrime[i] = false
			}
		}
	}

	primes := []int{}
	for i := 2; i < n; i++ {
		if isPrime[i] {
			primes = append(primes, i)
		}
	}

	return primes
}
