// i represents the number of stones in the level (i+1).
// Examples:
// >>> make_a_pile(3)
// []int{3, 5, 7}
func make_a_pile(n int) []int {
	if n <= 0 {
		return []int{}
	}

	pile := make([]int, n)
	currentLevel := n
	pile[0] = n

	for i := 1; i < n; i++ {
		if n%2 != 0 {
			// n is odd, next level is the next odd number
			currentLevel += 2
		} else {
			// n is even, next level is the next even number
			currentLevel += 2
		}
		pile[i] = currentLevel
	}

	return pile
}
