// Write a function count_nums which takes a list of integers and returns
// the number of elements which has a sum of digits > 0.
// If a number is negative, then its first signed digit will be negative:
// e.g. -123 has signed digits -1, 2, and 3.
// >>> count_nums([]int{})
// 0
// >>> count_nums([]int{-1, 11, -11})
// 1
// >>> count_nums([]int{1, 1, 2})
// 3
func count_nums(arr []int) int {
	count := 0
	for _, num := range arr {
		sum := 0
		temp := num
		isNegative := false

		if temp < 0 {
			isNegative = true
			temp = -temp // Work with the absolute value for digit extraction
		}

		if temp == 0 {
			// Sum of digits for 0 is 0, which is not > 0
			continue
		}

		// Extract digits
		for temp > 0 {
			digit := temp % 10
			sum += digit
			temp /= 10
		}

		// Adjust sum for the sign of the first digit if the number was negative
		// The problem states: "-123 has signed digits -1, 2, and 3."
		// This implies the first digit's sign is applied to the sum.
		// If the number is negative, the first digit (most significant) is negative.
		// For -123, the digits are 1, 2, 3. The first digit is 1, but it's signed as -1.
		// The sum of signed digits should be -1 + 2 + 3 = 4.
		// If we just sum the absolute digits (1+2+3=6), we need to subtract 2*1 to get -1+2+3.
		// A simpler interpretation based on the examples:
		// -1: sum of digits is 1. Signed digit is -1. Sum = -1.
		// 11: sum of digits is 2. Sum = 2.
		// -11: sum of digits is 2. Signed digits are -1, -1. Sum = -2.

		// Let's re-evaluate the rule based on the examples:
		// -1: Digits are 1. Signed digit is -1. Sum = -1.
		// 11: Digits are 1, 1. Sum = 2.
		// -11: Digits are 1, 1. Signed digits are -1, -1. Sum = -2.

		if isNegative {
			// We need to find the most significant digit (MSD) and apply the negative sign to it.
			// The current 'sum' is the sum of absolute digits.
			// We need to subtract 2 * MSD from the sum.

			// Re-calculate MSD for negative numbers
			tempAbs := -num
			msd := tempAbs
			for msd >= 10 {
				msd /= 10
			}

			// The sum of signed digits = (Sum of absolute digits) - 2 * MSD
			// Example -123: Sum of abs digits = 6. MSD = 1. Signed sum = 6 - 2*1 = 4.
			// Example -11: Sum of abs digits = 2. MSD = 1. Signed sum = 2 - 2*1 = 0.

			// Wait, the example says: "-123 has signed digits -1, 2, and 3."
			// Sum = -1 + 2 + 3 = 4.
			// If we use the absolute digits (1, 2, 3), the sum is 6.
			// The difference is 2. This is 2 * MSD.

			// Let's stick to the logic: Sum = (Sum of absolute digits) - 2 * MSD
			sum = sum - 2*msd
		}

		if sum > 0 {
			count++
		}
	}
	return count
}
