// You should return a list containing the result string and true/false for the check.
// Example
// >>> reverse_delete("abcde", "ae")
// []interface{}{"bcd", false}
// >>> reverse_delete("abcdef", "b")
// []interface{}{"acdef", false}
// >>> reverse_delete("abcdedcba", "ab")
// []interface{}{"cdedc", true}
func reverse_delete(s string, c string) []interface{} {
	// Create a set of characters to delete from c
	charsToDelete := make(map[rune]bool)
	for _, char := range c {
		charsToDelete[char] = true
	}

	// Build the result string by excluding characters present in c
	var result strings.Builder
	for _, char := range s {
		if !charsToDelete[char] {
			result.WriteRune(char)
		}
	}
	resultStr := result.String()

	// Check if the result string is a palindrome
	isPalindrome := true
	n := len(resultStr)
	for i := 0; i < n/2; i++ {
		if resultStr[i] != resultStr[n-1-i] {
			isPalindrome = false
			break
		}
	}

	return []interface{}{resultStr, isPalindrome}
}
