func is_nested(myString string) bool {
	// A bracket is "nested" if it is part of a structure like [[]] or [[...]]
	// and not just a simple adjacent pair like [] or [][].

	// We can track the current nesting level.
	// If the nesting level ever reaches 2 or more, it means we have at least one
	// bracket that is nested inside another pair.

	level := 0
	for _, char := range myString {
		if char == '[' {
			level++
			// If the level is 2 or more, it means we have at least one pair
			// enclosed within another pair (e.g., in "[[]]", the inner '['
			// makes the level 2).
			if level >= 2 {
				return true
			}
		} else if char == ']' {
			level--
		}
	}

	// If the loop finishes and we never reached a level of 2, no bracket was nested.
	return false
}
