// simplify checks if the product of two fractions x and n results in a whole number.
// Both x and n are strings in the format "<numerator>/<denominator>".
func simplify(x string, n string) bool {
	// Parse fraction x
	partsX := splitFraction(x)
	numX := new(big.Int)
	denX := new(big.Int)
	numX.SetString(partsX[0], 10)
	denX.SetString(partsX[1], 10)

	// Parse fraction n
	partsN := splitFraction(n)
	numN := new(big.Int)
	denN := new(big.Int)
	numN.SetString(partsN[0], 10)
	denN.SetString(partsN[1], 10)

	// The product of x * n is:
	// (numX / denX) * (numN / denN) = (numX * numN) / (denX * denN)

	// Calculate the numerator of the product: numX * numN
	productNum := new(big.Int).Mul(numX, numN)

	// Calculate the denominator of the product: denX * denN
	productDen := new(big.Int).Mul(denX, denN)

	// The product is a whole number if and only if the numerator is divisible by the denominator.
	// We use Mod to check for divisibility. If productNum % productDen == 0, it's a whole number.
	remainder := new(big.Int).Mod(productNum, productDen)

	return remainder.Cmp(big.NewInt(0)) == 0
}

// splitFraction parses a fraction string "num/den" into a slice of strings [num, den].
func splitFraction(fraction string) []string {
	var numStr, denStr string
	for i, char := range fraction {
		if char == '/' {
			numStr = fraction[:i]
			denStr = fraction[i+1:]
			break
		}
	}
	return []string{numStr, denStr}
}
