// has_close_elements checks if in the given list of numbers, there are any two numbers
// closer to each other than the given threshold.
// The function sorts the numbers first, as the closest elements must be adjacent
// in a sorted list.
func has_close_elements(numbers []float64, threshold float64) bool {
	if len(numbers) < 2 {
		return false
	}

	// Create a copy and sort it to avoid modifying the input slice
	sortedNumbers := make([]float64, len(numbers))
	copy(sortedNumbers, numbers)
	sort.Float64s(sortedNumbers)

	// Check the difference between adjacent elements
	for i := 0; i < len(sortedNumbers)-1; i++ {
		diff := math.Abs(sortedNumbers[i+1] - sortedNumbers[i])
		if diff < threshold {
			return true
		}
	}

	return false
}
