package mean_absolute_deviation_test

import (
	"math"
)

// For a given list of input numbers, calculate Mean Absolute Deviation
// around the mean of this dataset.
// Mean Absolute Deviation is the average absolute difference between each
// element and a centerpoint (mean in this case):
// MAD = average | x - x_mean |
func mean_absolute_deviation(numbers []float64) float64 {
	if len(numbers) == 0 {
		return 0.0
	}

	// 1. Calculate the mean
	var sum float64
	for _, n := range numbers {
		sum += n
	}
	mean := sum / float64(len(numbers))

	// 2. Calculate the sum of absolute differences from the mean
	var absoluteDifferencesSum float64
	for _, n := range numbers {
		diff := math.Abs(n - mean)
		absoluteDifferencesSum += diff
	}

	// 3. Calculate the mean of the absolute differences
	mad := absoluteDifferencesSum / float64(len(numbers))
	return mad
}
