import (
	"math"
)

// largest_divisor finds the largest number that divides n evenly, smaller than n.
// For a given number n, find the largest number that divides n evenly, smaller than n
// >>> largest_divisor(15)
// 5
func largest_divisor(n int) int {
	if n <= 1 {
		return 1 // Or handle as an error/specific case, but for positive integers > 1, this is safe.
	}
	// The largest divisor smaller than n is n divided by its smallest prime factor.
	// We can find the smallest divisor greater than 1 by checking from 2 up to sqrt(n).
	for i := 2; i*i <= n; i++ {
		if n%i == 0 {
			return n / i
		}
	}
	// If no divisor is found up to sqrt(n), n must be prime.
	// The largest divisor of a prime number n (smaller than n) is 1.
	return 1
}
