import (
	"reflect"
)

// Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
func fizz_buzz(n int) int {
	count := 0
	for i := 1; i < n; i++ {
		if i%11 == 0 || i%13 == 0 {
			s := ""
			for j := i; j > 0; j /= 10 {
				s = string(rune('0'+j%10)) + s
			}
			if containsDigit7(s) {
				count++
			}
		}
	}
	return count
}

func containsDigit7(s string) bool {
	for _, char := range s {
		if char == '7' {
			return true
		}
	}
	return false
}
