package triples_sum_to_zero_test

import (
	"reflect"
)

// triples_sum_to_zero takes a list of integers as an input.
// it returns true if there are three distinct elements in the list that
// sum to zero, and false otherwise.
func triples_sum_to_zero(l []int) bool {
	n := len(l)
	if n < 3 {
		return false
	}

	// Use a map to store seen numbers for O(1) lookups
	seen := make(map[int]bool)

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			// We are looking for a third element k such that l[i] + l[j] + l[k] = 0
			// This means l[k] = -(l[i] + l[j])
			target := -(l[i] + l[j])

			// Check if the target exists in the rest of the array (after j)
			// Since we need three *distinct* elements, we must ensure the target
			// is not l[i] or l[j] itself, and it must appear at an index k > j.
			// A simpler approach for distinct indices is to iterate over all pairs (i, j)
			// and check if the required third element exists in the remaining part of the array.

			// Let's use a set/map approach for O(N^2) complexity, which is simpler to implement
			// while ensuring distinct indices.

			// Re-implement using a set of all elements for O(N^2) check,
			// but we must handle the distinct index requirement carefully.

			// A cleaner O(N^2) approach:
			// Iterate over all pairs (i, j) where i < j.
			// Check if -(l[i] + l[j]) exists in the array at an index k != i and k != j.
			for k := j + 1; k < n; k++ {
				if l[i]+l[j]+l[k] == 0 {
					return true
				}
			}
		}
	}

	return false
}
