package change_base_test

import (
	"fmt"
)

// Change numerical base of input number x to base.
// return string representation after the conversion.
// base numbers are less than 10.
func change_base(x int, base int) string {
	if x == 0 {
		return "0"
	}

	if base < 2 || base >= 10 {
		// Based on the prompt constraints, this case might not be strictly necessary,
		// but it's good practice.
		return ""
	}

	result := ""
	for x > 0 {
		remainder := x % base
		// Since base < 10, the remainder will always be a digit 0-9
		result = fmt.Sprintf("%d", remainder) + result
		x = x / base
	}
	return result
}
