package correct_bracketing_test

// brackets is a string of "<" and ">".
// return true if every opening bracket has a corresponding closing bracket.
func correct_bracketing(brackets string) bool {
	count := 0
	for _, char := range brackets {
		if char == '<' {
			count++
		} else if char == '>' {
			count--
		}
		// If count drops below zero, it means we encountered a closing bracket
		// without a corresponding opening bracket.
		if count < 0 {
			return false
		}
	}
	// For the bracketing to be correct, the final count must be zero.
	return count == 0
}
