package vowels_count_test

import (
	"strings"
)

// vowels_count takes a string representing a word as input and returns the number of vowels in the string.
// Vowels are 'a', 'e', 'i', 'o', 'u' (case-insensitive). 'y' is also a vowel, but only when it is at the end of the given word.
func vowels_count(s string) int {
	count := 0
	runes := []rune(s)
	n := len(runes)

	for i, r := range runes {
		lowerR := strings.ToLower(string(r))
		isVowel := false

		// Check for standard vowels
		if lowerR == "a" || lowerR == "e" || lowerR == "i" || lowerR == "o" || lowerR == "u" {
			isVowel = true
		}

		// Check for 'y' at the end of the word
		if lowerR == "y" && i == n-1 {
			isVowel = true
		}

		if isVowel {
			count++
		}
	}
	return count
}
