package pluck_test

import (
	"math"
)

// pluck finds the node with the smallest even value in a list.
// If multiple nodes have the same smallest even value, it returns the one with the smallest index.
// The result is returned as [smallest_value, its_index].
// If no even values exist or the list is empty, it returns [].
func pluck(arr []int) []int {
	if len(arr) == 0 {
		return []int{}
	}

	smallestEvenValue := math.MaxInt32
	smallestEvenIndex := -1

	for i, val := range arr {
		// Check if the value is even and non-negative (constraint guarantees non-negative)
		if val%2 == 0 {
			// Check if this even value is smaller than the current smallest even value found
			if val < smallestEvenValue {
				smallestEvenValue = val
				smallestEvenIndex = i
			} else if val == smallestEvenValue {
				// If values are equal, we prefer the one with the smallest index.
				// Since we iterate from left to right (i increases), the first one found
				// for a given smallestEvenValue will naturally have the smallest index.
				// We only update if the new index is smaller, but since we are iterating
				// sequentially, we don't need to do anything here if val == smallestEvenValue.
				// The current smallestEvenIndex already holds the smallest index found so far for this value.
			}
		}
	}

	if smallestEvenIndex == -1 {
		// No even values found
		return []int{}
	}

	return []int{smallestEvenValue, smallestEvenIndex}
}
