package will_it_fly_test

import (
	"reflect"
)

// will_it_fly returns true if the object q will fly, and false otherwise.
// The object q will fly if it's balanced (it is a palindromic list) and the sum of its elements is less than or equal the maximum possible weight w.
func will_it_fly(q []int, w int) bool {
	// Check if the list is balanced (palindromic)
	isBalanced := true
	for i := 0; i < len(q)/2; i++ {
		if q[i] != q[len(q)-1-i] {
			isBalanced = false
			break
		}
	}

	if !isBalanced {
		return false
	}

	// Check if the sum of elements is less than or equal to w
	sum := 0
	for _, val := range q {
		sum += val
	}

	return sum <= w
}
