package is_simple_power_test

import (
	"math"
)

// is_simple_power returns true if x is a simple power of n (n^int = x) and false otherwise.
// The exponent 'int' must be an integer greater than 1 based on the examples provided.
func is_simple_power(x int, n int) bool {
	// Handle edge cases based on mathematical properties and examples.

	// If n is 1, x must be 1 (1^int = 1).
	if n == 1 {
		return x == 1
	}

	// If x is 1, it is a power of any n (n^0 = 1), but the examples suggest the exponent must be > 1.
	// Since the examples show n^2, n^3, etc., we assume the exponent must be >= 2.
	if x == 1 {
		return false
	}

	// If n is 0, the only power is 0^k = 0 (for k>0). 0^0 is usually 1.
	if n == 0 {
		return x == 0 && x != 1
	}

	// If n is negative, the behavior depends on the exponent parity, but given the examples
	// use positive integers, we'll focus on positive bases for simplicity unless necessary.
	if n < 0 {
		// For simplicity and alignment with typical "simple power" definitions in introductory problems,
		// we assume positive bases. If negative bases were required, more complex logic for even/odd exponents would be needed.
		return false
	}

	// If x is less than or equal to 0 (and n > 1), it cannot be a positive integer power of n.
	if x <= 0 {
		return false
	}

	// We need to find if there exists an integer 'p' >= 2 such that n^p = x.
	// We can do this by repeatedly dividing x by n until we reach 1 or the division is no longer exact.

	current := x
	for p := 0; current > 1; p++ {
		if current%n != 0 {
			return false
		}
		current /= n
	}

	// If we successfully reduced x to 1, we need to ensure the exponent used (p+1) was >= 2.
	// Since we started the loop with current = x, if x > 1, the loop runs at least once, meaning p >= 0, so p+1 >= 1.
	// We must explicitly check if the exponent is at least 2.
	// If x was 1 initially, we returned false. If x > 1, and we reached 1, the exponent is at least 1.
	// If x = n^1, the loop runs once, p=0, current becomes 1. We return true, but the spec says n^1 is false.
	// Let's re-evaluate the loop structure to track the exponent explicitly.

	if x == n {
		return false // n^1 = x, but the spec requires exponent > 1
	}

	// Reset and use a loop that checks for exponent >= 2
	exponent := 0
	temp := x
	for temp > 1 {
		if temp%n != 0 {
			return false
		}
		temp /= n
		exponent++
	}

	return exponent >= 2
}
