func any_int(x float64, y float64, z float64) bool {
	// Check if all numbers are integers
	if math.Abs(x-math.Round(x)) > 1e-9 ||
		math.Abs(y-math.Round(y)) > 1e-9 ||
		math.Abs(z-math.Round(z)) > 1e-9 {
		return false
	}

	// Check the sum condition
	// Since we've confirmed they are integers, we can safely cast them to integers for comparison
	// or just use the float arithmetic which should be exact for integers within float64 range.
	return (x+y == z) || (x+z == y) || (y+z == x)
