package count_up_to_test

import (
	"math"
)

// count_up_to takes a non-negative integer n and returns a list of the first n
// integers that are prime numbers and less than n.
// NOTE: The prompt description is slightly ambiguous. Based on the examples:
// count_up_to(5) -> []int{2, 3} (Primes < 5)
// count_up_to(11) -> []int{2, 3, 5, 7} (Primes < 11)
// It seems the function should return all prime numbers strictly less than n.
func count_up_to(n int) []int {
	if n <= 2 {
		return []int{}
	}

	primes := []int{}

	// Helper function to check for primality
	isPrime := func(num int) bool {
		if num <= 1 {
			return false
		}
		if num <= 3 {
			return true
		}
		if num%2 == 0 || num%3 == 0 {
			return false
		}
		// Check divisors up to sqrt(num)
		limit := int(math.Sqrt(float64(num)))
		for i := 5; i <= limit; i = i + 6 {
			if num%i == 0 || num%(i+2) == 0 {
				return false
			}
		}
		return true
	}

	// Iterate from 2 up to n-1
	for i := 2; i < n; i++ {
		if isPrime(i) {
			primes = append(primes, i)
		}
	}

	return primes
}
