package unique_digits_test

import (
	"sort"
)

// unique_digits returns a sorted list of all elements from x that do not contain any even digits.
// Note: Returned list should be sorted in increasing order.
func unique_digits(x []int) []int {
	var result []int

	for _, num := range x {
		if hasOnlyOddDigits(num) {
			result = append(result, num)
		}
	}

	sort.Ints(result)
	return result
}

// hasOnlyOddDigits checks if a number contains only odd digits (1, 3, 5, 7, 9).
func hasOnlyOddDigits(n int) bool {
	if n == 0 {
		return false // 0 is an even digit
	}
	for n > 0 {
		digit := n % 10
		if digit%2 == 0 {
			return false // Found an even digit
		}
		n /= 10
	}
	return true
}
