// count_nums takes a list of integers and returns the number of elements which has a sum of digits > 0.
// If a number is negative, then its first signed digit will be negative:
// e.g. -123 has signed digits -1, 2, and 3.
func count_nums(arr []int) int {
	count := 0
	for _, num := range arr {
		sum := 0
		temp := num

		if temp == 0 {
			// Sum of digits for 0 is 0, which is not > 0.
			continue
		}

		isNegative := temp < 0
		if isNegative {
			temp = -temp
		}

		// Handle the first digit's sign based on the requirement:
		// "If a number is negative, then its first signed digit will be negative"
		// This implies we need to extract the first digit and apply the sign if negative.
		// However, the examples suggest a simpler interpretation:
		// -123 -> digits are -1, 2, 3. Sum = -1 + 2 + 3 = 4. 4 > 0. Count it.
		// -11 -> digits are -1, -1. Sum = -2. -2 is not > 0. Don't count it.
		// -1 -> digit is -1. Sum = -1. -1 is not > 0. Don't count it.

		// Let's re-evaluate the requirement based on the examples:
		// Example 1: count_nums([]int{-1, 11, -11}) -> 1
		// -1: Digits are -1. Sum = -1. Not > 0.
		// 11: Digits are 1, 1. Sum = 2. > 0. Count it.
		// -11: Digits are -1, -1. Sum = -2. Not > 0.
		// Result: 1. This matches the example.

		// Example 2: count_nums([]int{1, 1, 2}) -> 3
		// 1: Sum = 1. > 0.
		// 1: Sum = 1. > 0.
		// 2: Sum = 2. > 0.
		// Result: 3. This matches the example.

		// Implementation based on the derived rule:
		// If negative, the first digit is negative, subsequent digits are positive.

		if isNegative {
			// Extract the first digit (which will be negative)
			// For -123, temp is 123. The first digit is 1. We treat it as -1.
			firstDigit := int(math.Floor(float64(temp)/math.Pow10(len(fmt.Sprintf("%d", temp))-1)))
			sum += -firstDigit

			// Process remaining digits (which are positive)
			remaining := temp / firstDigit
			for remaining > 0 {
				sum += remaining % 10
				remaining /= 10
			}
		} else {
			// Positive number: all digits are positive
			for temp > 0 {
				sum += temp % 10
				temp /= 10
			}
		}

		if sum > 0 {
			count++
		}
	}
	return count
