package reverse_delete_test

import (
	"strings"
	"reflect"
)

// reverse_delete deletes all characters in s that are present in c,
// and then checks if the resulting string is a palindrome.
// It returns a slice containing the resulting string and a boolean indicating if it's a palindrome.
func reverse_delete(s string, c string) []interface{} {
	// Create a set of characters to delete for efficient lookup
	deleteChars := make(map[rune]bool)
	for _, char := range c {
		deleteChars[char] = true
	}

	// Build the result string by excluding characters in c
	var result strings.Builder
	for _, char := range s {
		if !deleteChars[char] {
			result.WriteRune(char)
		}
	}
	resultStr := result.String()

	// Check if the result string is a palindrome
	isPalindrome := true
	n := len(resultStr)
	for i := 0; i < n/2; i++ {
		if resultStr[i] != resultStr[n-1-i] {
			isPalindrome = false
			break
		}
	}

	return []interface{}{resultStr, isPalindrome}
}
