		// Helper function to count set bits (ones) in the binary representation
		countOnes := func(n int) int {
			if n < 0 {
				// For negative numbers, we count ones in their two's complement representation.
				// Since Go's int size is implementation-dependent (usually 32 or 64 bits),
				// we cast to uint to handle the bitwise operations consistently for the count.
				// The behavior for negative numbers in the prompt examples suggests standard
				// lexicographical sorting for ties, but the primary key is the count of ones.
				// For simplicity and consistency with standard bit counting, we use the
				// bitwise AND trick on the unsigned representation.
				return countSetBits(uint(n))
			}
			return countSetBits(uint(n))
		}

		// Standard bit counting algorithm (Brian Kernighan's Algorithm)
		countSetBits := func(n uint) int {
			count := 0
			for n > 0 {
				n &= (n - 1)
				count++
			}
			return count
		}

		onesI := countOnes(result[i])
		onesJ := countOnes(result[j])

		if onesI != onesJ {
			// Primary sort key: ascending order of ones
			return onesI < onesJ
		}
		// Secondary sort key: ascending order of decimal value
		return result[i] < result[j]
	})

	return result
}
