package maximum_test

import (
	"sort"
)

// Given a list arr of integers and a positive integer k, return a sorted list 
// of length k with the maximum k numbers in arr.
// Example 1:
// >>> maximum([]int{-3, -4, 5}, 3)
// []int{-4, -3, 5}
// Example 2:
// >>> maximum([]int{4, -4, 4}, 2)
// []int{4, 4}
// Example 3:
// >>> maximum([]int{-3, 2, 1, 2, -1, -2, 1}, 1)
// []int{2}
// Note:
// 1. The length of the list will be in the range of [1, 1000].
// 2. The elements in the list will be in the range of [-1000, 1000].
// 3. 0 <= k <= len(arr)
func maximum(arr []int, k int) []int {
	if k == 0 {
		return []int{}
	}

	// Create a copy of the array to avoid modifying the original slice
	temp := make([]int, len(arr))
	copy(temp, arr)

	// Sort the array in ascending order
	sort.Ints(temp)

	// The k largest elements will be at the end of the sorted array.
	// We need to return them in sorted order (which they are if we take the last k elements).
	// Since the requirement is to return a "sorted list of length k", we take the last k elements.
	result := temp[len(temp)-k:]
	return result
}
