// valid_date validates a given date string based on specific rules.
func valid_date(date string) bool {
	// Rule 1: The date string is not empty.
	if date == "" {
		return false
	}

	// Rule 4: The date should be in the format: mm-dd-yyyy
	parts := strings.Split(date, "-")
	if len(parts) != 3 {
		return false
	}

	monthStr, dayStr, yearStr := parts[0], parts[1], parts[2]

	// Check if parts are valid integers
	month, errM := parsePart(monthStr)
	day, errD := parsePart(dayStr)
	year, errY := parsePart(yearStr)

	if errM != nil || errD != nil || errY != nil {
		return false
	}

	// Rule 3: The months should not be less than 1 or higher than 12.
	if month < 1 || month > 12 {
		return false
	}

	// Rule 2: Check day validity based on month and year
	var maxDays int
	switch month {
	case 1, 3, 5, 7, 8, 10, 12:
		maxDays = 31
	case 4, 6, 9, 11:
		maxDays = 30
	case 2:
		// Check for leap year
		if year%4 == 0 && year%100 != 0 {
			maxDays = 29
		} else if year%4 == 0 && year%100 == 0 {
			maxDays = 29 // Century leap years are divisible by 400
		} else if year%100 == 0 && year%400 == 0 {
			maxDays = 29
		} else {
			maxDays = 28
		}
	default:
		// Should be caught by Rule 3, but as a safeguard
		return false
	}

	// Check day constraints (Rule 2)
	if day < 1 || day > maxDays {
		return false
	}

	// Additional check for leading zeros requirement implied by format mm-dd-yyyy
	// If month or day are single digits, they should have been padded in the input string.
	// Since we parsed them as integers, we check the original string length.
	if len(monthStr) != 2 || len(dayStr) != 2 || len(yearStr) != 4 {
		return false
	}

	return true
}

// Helper function to parse string to int, ensuring it's not empty
func parsePart(s string) (int, error) {
	if s == "" {
		return 0, fmt.Errorf("empty string")
	}
	var val int
	_, err := fmt.Sscanf(s, "%d", &val)
	if err != nil {
		return 0, fmt.Errorf("invalid integer format")
	}
	return val, nil
}
