package is_nested_test

import (
	"fmt"
)

// is_nested checks if there is a valid subsequence of brackets where at least one bracket is nested.
// A valid subsequence implies that the brackets form a well-formed structure, and nesting occurs
// when a pair of brackets encloses another pair (e.g., [[]]).
//
// The logic implemented here checks if there is any instance of a pair of brackets
// that contains another pair of brackets within the string, while maintaining overall
// structural validity for the purpose of identifying nesting.
func is_nested(myString string) bool {
	// A simple way to detect nesting is to check if any opening bracket '['
	// is followed by another opening bracket '[' before its corresponding closing bracket ']'.
	// This is equivalent to checking if the maximum depth of the bracket sequence is greater than 1.

	maxDepth := 0
	currentDepth := 0

	for _, char := range myString {
		if char == '[' {
			currentDepth++
			if currentDepth > maxDepth {
				maxDepth = currentDepth
			}
		} else if char == ']' {
			currentDepth--
		}
	}

	// If maxDepth is 0 or 1, there is no nesting (e.g., "[]", "[] []").
	// If maxDepth >= 2, there is at least one level of nesting (e.g., "[[]]").
	return maxDepth >= 2
}
