// simplify checks if the product of two fractions x and n results in a whole number.
// Both x and n are strings in the format "<numerator>/<denominator>".
func simplify(x string, n string) bool {
	// Parse fraction x
	partsX := splitFraction(x)
	numX, _ := strconv.ParseInt(partsX[0], 10, 64)
	denX, _ := strconv.ParseInt(partsX[1], 10, 64)

	// Parse fraction n
	partsN := splitFraction(n)
	numN, _ := strconv.ParseInt(partsN[0], 10, 64)
	denN, _ := strconv.ParseInt(partsN[1], 10, 64)

	// The product is (numX * numN) / (denX * denN)
	// We need to check if (numX * numN) is divisible by (denX * denN).

	// Use big.Int for multiplication to prevent overflow, although for standard int64,
	// the product might exceed it. Since the problem implies whole numbers, we use big.Int for safety.
	bigNumX := big.NewInt(numX)
	bigNumN := big.NewInt(numN)
	bigDenX := big.NewInt(denX)
	bigDenN := big.NewInt(denN)

	// Calculate numerator of the product: numX * numN
	productNum := new(big.Int).Mul(bigNumX, bigNumN)

	// Calculate denominator of the product: denX * denN
	productDen := new(big.Int).Mul(bigDenX, bigDenN)

	// Check if productNum is divisible by productDen (remainder is 0)
	remainder := new(big.Int)
	remainder.Mod(productNum, productDen)

	return remainder.Cmp(big.NewInt(0)) == 0
}

// Helper function to split the fraction string
func splitFraction(s string) []string {
	var parts []string
	for _, part := range []byte(s) {
		if part == '/' {
			parts = append(parts, string(part))
			continue
		}
		parts = append(parts, string(part))
	}
	// A simpler split implementation for the expected format
	var res []string
	var current string
	for _, char := range s {
		if char == '/' {
			res = append(res, current)
			current = ""
		} else {
			current += string(char)
		}
	}
	res = append(res, current)
	return res
}
