// PlanetOrder maps planet names to their order of proximity to the sun (0-indexed).
var PlanetOrder = map[string]int{
	"Mercury": 0,
	"Venus":   1,
	"Earth":    2,
	"Mars":     3,
	"Jupiter":  4,
	"Saturn":   5,
	"Uranus":   6,
	"Neptune":  7,
}

// bf returns a list containing all planets whose orbits are located between the orbit of planet1 and planet2, sorted by proximity to the sun.
// It returns an empty list if planet1 or planet2 are not correct planet names.
func bf(planet1 string, planet2 string) []interface{} {
	order1, ok1 := PlanetOrder[planet1]
	order2, ok2 := PlanetOrder[planet2]

	if !ok1 || !ok2 {
		return []interface{}{}
	}

	// Determine the start and end indices for the range.
	// We want planets strictly between the two given planets.
	start := min(order1, order2) + 1
	end := max(order1, order2)

	if start > end {
		return []interface{}{}
	}

	var result []interface{}
	// Iterate through the planets in order
	for i := start; i <= end; i++ {
		// Find the planet corresponding to index i
		for name, order := range PlanetOrder {
			if order == i {
				result = append(result, name)
				break
			}
		}
	}

	return result
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
