// Given a positive integer, obtain its roman numeral equivalent as a string,
// and return it in lowercase.
// Restrictions: 1 <= num <= 1000
// Examples:
// >>> int_to_mini_roman(19)
// "xix"
// >>> int_to_mini_roman(152)
// "clii"
// >>> int_to_mini_roman(426)
// "cdxxvi"
func int_to_mini_roman(number int) string {
	if number < 1 || number > 1000 {
		return "" // Should not happen based on constraints
	}

	// Mapping for Roman numerals (lowercase)
	// We use the standard subtractive notation for efficiency (e.g., 4 as iv, 9 as ix)
	values := []struct {
		val  int
		sym  string
	}{
		{1000, "m"},
		{900, "cm"},
		{500, "d"},
		{400, "cd"},
		{100, "c"},
		{90, "xc"},
		{50, "l"},
		{40, "xl"},
		{10, "x"},
		{9, "ix"},
		{5, "v"},
		{4, "iv"},
		{1, "i"},
	}

	result := ""
	for _, mapping := range values {
		for number >= mapping.val {
			result += mapping.sym
			number -= mapping.val
		}
	}
	return result
}
