			return a * b
		case "//":
			return a / b // Go integer division is floor division for positive results
		case "**":
			// Since operands are non-negative, we can use math.Pow logic, but for simplicity and integer return,
			// we use a loop or math.Pow and cast. Since we are dealing with integers, we'll use a simple loop for power.
			res := 1
			for i := 0; i < b; i++ {
				res *= a
			}
			return res
		default:
			panic("Unknown operator")
		}
	}

	// Pass 1: Multiplication and Exponentiation (and Floor Division if we treat it like multiplication precedence)
	// Standard precedence: *, // > +, -

	// We will use a stack-like approach or iterative reduction.
	// Since we only have two levels of precedence (high and low), we can simplify the expression iteratively.

	// First, handle multiplication and exponentiation
	tempOperands := make([]int, len(operand))
	copy(tempOperands, operand)
	tempOperators := make([]string, len(operator))
	copy(tempOperators, operator)

	// Loop until no high-precedence operations remain
	for {
		foundHighPrecedence := false
		newOperands := []int{}
		newOperators := []string{}

		if len(tempOperands) == 0 {
			break
		}

		// Start with the first operand
		currentVal := tempOperands[0]

		for i := 0; i < len(tempOperators); i++ {
			op := tempOperators[i]
			nextVal := tempOperands[i+1]

			if op == "*" || op == "/" || op == "**" {
				// Apply high precedence operation
				currentVal = applyOp(op, currentVal, nextVal)
				foundHighPrecedence = true
			} else {
				// Low precedence operation (+ or -). Finalize the current accumulated value.
				newOperands = append(newOperands, currentVal)

				// If there are more operators, append the low precedence operator
				if i+1 < len(tempOperators) {
					newOperators = append(newOperators, op)
				}

				// Start accumulating the next value
				currentVal = nextVal
			}
		}
		// Append the last accumulated value
		newOperands = append(newOperands, currentVal)

		tempOperands = newOperands
		tempOperators = newOperators

		if !foundHighPrecedence {
			break
		}
	}

	// Step 2: Handle addition and subtraction (left-to-right evaluation)
	if len(tempOperands) == 0 {
		return 0
	}

	result := tempOperands[0]
	for i := 0; i < len(tempOperators); i++ {
		op := tempOperators[i]
		nextVal := tempOperands[i+1]
		result = applyOp(op, result, nextVal)
	}

	return result
}
