/// Example 3:
/// >>> pluck(vec![])
/// Vec::<isize>::new()
/// Example 4:
/// >>> pluck(vec![5, 0, 3, 0, 4, 2])
/// vec![0, 1]
/// Explanation: 0 is the smallest value, but  there are two zeros,
/// so we will choose the first zero, which has the smallest index.
/// Constraints:
/// * 1 <= nodes.length <= 10000
/// * 0 <= node.value
fn pluck(arr: Vec<isize>) -> Vec<isize> {
    let mut smallest_even_value = isize::MAX;
    let mut smallest_even_index = None;

    for (index, &value) in arr.iter().enumerate() {
        // Check if the value is even and non-negative (guaranteed by constraints)
        if value % 2 == 0 {
            // Check if this even value is smaller than the current smallest even value found
            if value < smallest_even_value {
                smallest_even_value = value;
                smallest_even_index = Some(index);
            } 
            // If the value is equal to the current smallest even value, we do nothing
            // because the current index (from the loop) will be greater than or equal to
            // the previously recorded index, and we want the smallest index.
            // Since we iterate from index 0 upwards, the first one found for a given value
            // will naturally have the smallest index.
        }
    }

    match smallest_even_index {
        Some(index) => vec![arr[index], index as isize],
        None => Vec::new(),
    }
}
