/// Your task is to write a function that returns true if a number x is a simple
/// power of n and false in other cases.
/// x is a simple power of n if n**int=x
/// For example:
/// >>> is_simple_power(1, 4)
/// true
/// >>> is_simple_power(2, 2)
/// true
/// >>> is_simple_power(8, 2)
/// true
/// >>> is_simple_power(3, 2)
/// false
/// >>> is_simple_power(3, 1)
/// false
/// >>> is_simple_power(5, 3)
/// false
fn is_simple_power(x: isize, n: isize) -> bool {
    if n <= 1 {
        // If n is 0 or 1, the only power that might match is x=1 (for n=1)
        // or x=0 (for n=0, if we consider 0^0=1 or 0^k=0).
        // Based on the examples, we are looking for n^int = x where int >= 2.
        // If n=1, 1^int = 1. If x=1, it's true for any int >= 2.
        if n == 1 {
            return x == 1;
        }
        // If n=0, 0^int = 0 for int >= 1. If x=0, it's true for int >= 1.
        if n == 0 {
            return x == 0 && x != 1; // 0^0 is often undefined or 1, but we need int >= 2 based on examples.
        }
        // For n < 0, the behavior is complex, but let's stick to positive bases for simplicity
        // unless x is 1 or -1.
        return false;
    }

    if x == 1 {
        // n^0 = 1 for any n != 0. Since we require int >= 2, this case is false.
        return false;
    }

    if x == 0 {
        // n^int = 0 implies n=0, which is handled above.
        return false;
    }

    // We are looking for an integer exponent 'int' >= 2 such that n^int = x.
    // We can find this by repeatedly dividing x by n until we reach 1 or a non-divisible number.

    let mut current_x = x;
    let mut exponent = 0;

    while current_x > 1 && current_x % n == 0 {
        current_x /= n;
        exponent += 1;
    }

    // If current_x is 1, it means x was perfectly divisible by n 'exponent' times.
    // We must also ensure the exponent is at least 2, as per the examples (e.g., is_simple_power(3, 1) is false).
    current_x == 1 && exponent >= 2
}
