fn sort_array(array: Vec<isize>) -> Vec<isize> {
    if array.len() <= 1 {
        return array;
    }

    let first = array[0];
    let last = array[array.len() - 1];
    let sum = first + last;

    if sum % 2 != 0 {
        // Odd sum: sort in ascending order
        let mut sorted_array = array.clone();
        sorted_array.sort();
        sorted_array
    } else {
        // Even sum: sort in descending order
        let mut sorted_array = array.clone();
        sorted_array.sort_by(|a, b| b.cmp(a));
        sorted_array
    }
}
