fn count_up_to(n: isize) -> Vec<isize> {
    if n <= 1 {
        return Vec::new();
    }

    let limit = n as usize;
    let mut is_prime = vec![true; limit + 1];
    is_prime[0] = false;
    is_prime[1] = false;

    for p in 2..=((limit as f64).sqrt() as usize) {
        if is_prime[p] {
            for i in (p * p..=limit).step_by(p) {
                is_prime[i] = false;
            }
        }
    }

    let mut primes = Vec::new();
    for i in 2..limit {
        if is_prime[i] {
            primes.push(i as isize);
        }
    }

    primes
}
