/// i represents the number of stones in the level (i+1).
/// Examples:
/// >>> make_a_pile(3)
/// vec![3, 5, 7]
fn make_a_pile(n: isize) -> Vec<isize> {
    let mut pile = Vec::with_capacity(n as usize);
    let mut current_stones = n;

    for _ in 0..n {
        pile.push(current_stones);

        if current_stones % 2 != 0 {
            // n is odd, next level is the next odd number
            current_stones += 2;
        } else {
            // n is even, next level is the next even number
            current_stones += 2;
        }
    }
