/// Write a function count_nums which takes a vector of integers and returns
/// the number of elements which has a sum of digits > 0.
/// If a number is negative, then its first signed digit will be negative:
/// e.g. -123 has signed digits -1, 2, and 3.
/// >>> count_nums(vec![])
/// 0
/// >>> count_nums(vec![-1, 11, -11])
/// 1
/// >>> count_nums(vec![1, 1, 2])
/// 3
fn count_nums(arr: Vec<isize>) -> isize {
    arr.iter().filter(|&&n| {
        let mut sum_of_digits: isize = 0;
        let mut temp_n = n;
        let is_negative = n < 0;

        if n == 0 {
            return false; // Sum of digits for 0 is 0, which is not > 0
        }

        if is_negative {
            // Handle the first signed digit (which is negative)
            let first_digit = (n / -10) % 10; // This is tricky for negative numbers, let's handle it explicitly

            // For -123, we want -1, 2, 3.
            // The absolute value is 123. Digits are 1, 2, 3.
            // The first digit is -1.

            let abs_n = n.abs();
            let mut s = String::new();
            let mut temp = abs_n;
            while temp > 0 {
                s.push((temp % 10) as u8);
                temp /= 10;
            }
            s.reverse();

            let digits: Vec<isize> = s.chars().map(|c| c.to_digit(10).unwrap() as isize).collect();

            // The first digit is negative
            let first_digit_val = -digits[0];
            sum_of_digits += first_digit_val;

            // The rest are positive
            for i in 1..digits.len() {
                sum_of_digits += digits[i];
            }
        } else {
            // Positive number
            let mut temp = n;
            while temp > 0 {
                sum_of_digits += temp % 10;
                temp /= 10;
            }
        }

        sum_of_digits > 0
    }).count() as isize
}
