/// >>> reverse_delete(String::from("abcdedcba"), String::from("ab"))
/// (String::from("cdedc"), true)
fn reverse_delete(s: String, c: String) -> (String, bool) {
    let chars_to_delete: std::collections::HashSet<char> = c.chars().collect();

    let result: String = s.chars()
        .filter(|&ch| !chars_to_delete.contains(&ch))
        .collect();

    let reversed_result: String = result.chars().rev().collect();
    let is_palindrome = result == reversed_result;

    (result, is_palindrome)
