    if numbers.len() < 2 {
        return false;
    }

    // Sorting the vector allows us to only compare adjacent elements,
    // as the minimum difference must occur between adjacent elements in a sorted list.
    let mut sorted_numbers = numbers;
    sorted_numbers.sort_by(|a, b| a.partial_cmp(b).unwrap());

    for i in 0..sorted_numbers.len() - 1 {
        let diff = (sorted_numbers[i + 1] - sorted_numbers[i]).abs();
        if diff < threshold {
            return true;
        }
    }

    false
}
