/// For a given number n, find the largest number that divides n evenly, smaller than n
/// >>> largest_divisor(15)
/// 5
fn largest_divisor(n: isize) -> isize {
    if n <= 1 {
        // For n <= 1, there is no positive divisor smaller than n.
        // Depending on requirements, one might return 1 or handle as an error.
        // Given the context of finding a divisor, we'll return 1 for n=1, 
        // though the prompt implies n > 1.
        return 1; 
    }

    // The largest divisor smaller than n is n divided by its smallest prime factor.
    // We iterate from 2 up to the square root of n to find the smallest factor.
    let n_abs = n.abs();
    let mut smallest_factor = n_abs;

    let limit = (n_abs as f64).sqrt() as isize;

    for i in 2..=limit {
        if n_abs % i == 0 {
            smallest_factor = i;
            break;
        }
    }

    // If smallest_factor is still n_abs, n is prime. The largest divisor is 1.
    if smallest_factor == n_abs {
        return 1;
    }

    // The largest divisor is n / smallest_factor.
    // Since we are dealing with isize, we must ensure the division is safe.
    // Since n > 1, n_abs > 1, and smallest_factor >= 2, this is safe.
    if n < 0 {
        // If n is negative, the largest divisor smaller than n (e.g., for -15, it's -5)
        // is - (n_abs / smallest_factor).
        return -(n_abs / smallest_factor);
    }

    n / smallest_factor
}
