/// triples_sum_to_zero takes a vector of integers as an input.
/// it returns true if there are three distinct elements in the vector that
/// sum to zero, and false otherwise.
/// >>> triples_sum_to_zero(vec![1, 3, 5, 0])
/// false
/// >>> triples_sum_to_zero(vec![1, 3, -2, 1])
/// true
/// >>> triples_sum_to_zero(vec![1, 2, 3, 7])
/// false
/// >>> triples_sum_to_zero(vec![2, 4, -5, 3, 9, 7])
/// true
/// >>> triples_sum_to_zero(vec![1])
/// false
fn triples_sum_to_zero(l: Vec<isize>) -> bool {
    let n = l.len();
    if n < 3 {
        return false;
    }

    // Sort the vector to use the two-pointer technique
    let mut sorted_l = l;
    sorted_l.sort();

    for i in 0..n - 2 {
        let mut left = i + 1;
        let mut right = n - 1;

        while left < right {
            let sum = sorted_l[i] + sorted_l[left] + sorted_l[right];
            if sum == 0 {
                // Found three distinct elements that sum to zero
                return true;
            } else if sum < 0 {
                // Sum is too small, need a larger value from the left
                left += 1;
            } else {
                // Sum is too large, need a smaller value from the right
                right -= 1;
            }
        }
    }

    false
}
```

