/// Change numerical base of input number x to base.
/// return string representation after the conversion.
/// base numbers are less than 10.
/// >>> change_base(8, 3)
/// String::from("22")
/// >>> change_base(8, 2)
/// String::from("1000")
/// >>> change_base(7, 2)
/// String::from("111")
fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return String::from("0");
    }

    let mut n = x;
    let mut result = String::new();
    let b = base as u32;

    while n > 0 {
        let remainder = (n % base) as u32;
        let digit = if remainder < 10 {
            char::from_digit(remainder, 10).unwrap()
        } else {
            // This case should not be reached given the constraint base < 10
            '?'
        };
        result.push(digit);
        n /= base;
    }

    result.chars().rev().collect()
}
