/// brackets is a string of "<" and ">".
/// return true if every opening bracket has a corresponding closing bracket.
/// >>> correct_bracketing(String::from("<"))
/// false
/// >>> correct_bracketing(String::from("<>"))
/// true
/// >>> correct_bracketing(String::from("<<><>>"))
/// true
/// >>> correct_bracketing(String::from("><<>"))
/// false
fn correct_bracketing(brackets: String) -> bool {
    let mut balance = 0;
    for c in brackets.chars() {
        if c == '<' {
            balance += 1;
        } else if c == '>' {
            balance -= 1;
        }
        // If balance drops below zero, it means we encountered a closing bracket
        // without a corresponding opening bracket.
        if balance < 0 {
            return false;
        }
    }
    // For the brackets to be correct, the final balance must be zero.
    balance == 0
}
```

