/// sum_to_n is a function that sums numbers from 1 to n.
/// >>> sum_to_n(30)
/// 465
/// >>> sum_to_n(100)
/// 5050
/// >>> sum_to_n(5)
/// 15
/// >>> sum_to_n(10)
/// 55
/// >>> sum_to_n(1)
/// 1
fn sum_to_n(n: isize) -> isize {
    if n < 1 {
        return 0;
    }
    // Using the formula for the sum of an arithmetic series: n * (n + 1) / 2
    // We cast to i64 for intermediate calculation to prevent overflow for large isize,
    // although for standard isize (i32), n=65535 is the limit.
    // Since the return type is isize, we cast back.
    let n_u64 = n as u64;
    let result = n_u64 * (n_u64 + 1) / 2;
    result as isize
}
