/// "Given a vector representing a branch of a tree that has non-negative integer nodes
/// your task is to pluck one of the nodes and return it.
/// The plucked node should be the node with the smallest even value.
/// If multiple nodes with the same smallest even value are found return the node that has smallest index.
/// The plucked node should be returned in a vector, [ smalest_value, its index ],
/// If there are no even values or the given vector is empty, return [].
/// Example 1:
/// >>> pluck(vec![4, 2, 3])
/// vec![2, 1]
/// Explanation: 2 has the smallest even value, and 2 has the smallest index.
/// Example 2:
/// >>> pluck(vec![1, 2, 3])
/// vec![2, 1]
/// Explanation: 2 has the smallest even value, and 2 has the smallest index.
/// Example 3:
/// >>> pluck(vec![])
/// Vec::<isize>::new()
/// Example 4:
/// >>> pluck(vec![5, 0, 3, 0, 4, 2])
/// vec![0, 1]
/// Explanation: 0 is the smallest value, but  there are two zeros,
/// so we will choose the first zero, which has the smallest index.
/// Constraints:
/// * 1 <= nodes.length <= 10000
/// * 0 <= node.value
fn pluck(arr: Vec<isize>) -> Vec<isize> {
    let mut smallest_even_value = isize::MAX;
    let mut smallest_even_index = None;

    for (index, &value) in arr.iter().enumerate() {
        // Check if the value is even and non-negative (guaranteed by constraints, but good practice)
        if value % 2 == 0 {
            // Check if this even value is smaller than the current smallest even value found
            if value < smallest_even_value {
                smallest_even_value = value;
                smallest_even_index = Some(index);
            } 
            // If the value is equal to the current smallest even value, we do nothing
            // because the current index (index) will be greater than or equal to the
            // previously recorded index (smallest_even_index.unwrap()), and we want the smallest index.
            // Since we iterate from index 0 upwards, the first one found for a given smallest_even_value
            // will naturally have the smallest index.
        }
    }

    match smallest_even_index {
        Some(index) => vec![smallest_even_value, index as isize],
        None => Vec::new(),
    }
}
```

