/// false
/// >>> is_simple_power(3, 1)
/// false
/// >>> is_simple_power(5, 3)
/// false
fn is_simple_power(x: isize, n: isize) -> bool {
    // Handle edge cases based on the definition n^int = x
    // The problem implies 'int' must be an integer exponent, and based on examples,
    // the exponent must be > 1 for the result to be considered a "simple power"
    // (e.g., is_simple_power(3, 1) is false).

    if n <= 0 {
        // Powers of non-positive numbers can be complex or undefined for integer exponents.
        // Given the examples, we assume n > 0.
        return false;
    }

    if x == 1 {
        // 1 is n^0 for any n != 0. If we require the exponent to be > 1, then 1 is not a simple power.
        // However, the example is_simple_power(1, 4) -> true. This implies that if x=1, it is true.
        // This suggests that if x=1, it is always considered a simple power, perhaps implying n^0=1 is allowed,
        // or that the test case (1, 4) is a special case.
        // Let's follow the example: is_simple_power(1, 4) is true.
        return true;
    }

    if n == 1 {
        // If n=1, the only power is 1 (1^int = 1). Since x != 1 here, it cannot be a power of 1.
        return false;
    }

    if n == x {
        // If n == x, then n^1 = x. Since the example is_simple_power(3, 1) is false,
        // we must exclude the exponent 1.
        return false;
    }

    // If x is a power of n, then x = n^k for some integer k >= 2.
    // We can find k by repeatedly dividing x by n until we reach 1.
    let mut current_x = x;
    let mut exponent = 0;

    while current_x > 1 && current_x % n == 0 {
        current_x /= n;
        exponent += 1;
    }

    // If current_x is 1, then x was a power of n.
    // We must also ensure the exponent is greater than 1, based on the example (3, 1) -> false.
    current_x == 1 && exponent >= 2
}
