/// Given a positive integer N, return the total sum of its digits in binary.
/// Example
/// >>> solve(1000)
/// String::from("1")
/// >>> solve(150)
/// String::from("110")
/// >>> solve(147)
/// String::from("1100")
/// Variables:
/// @N integer
/// Constraints: 0 ≤ N ≤ 10000.
/// Output:
/// a string of binary number
fn solve(N: isize) -> String {
    if N == 0 {
        return String::from("0");
    }

    let mut n = N;
    let mut binary_string = String::new();

    while n > 0 {
        let remainder = (n % 2) as u8;
        binary_string.insert(0, if remainder == 0 { '0' } else { '1' });
        n /= 2;
    }

    binary_string
}
