/// Given a vector of non-negative integers, return a cors of the given vector after sorting,
/// you will sort the given vector in ascending order if the sum( first index value, last index value) is odd,
/// or sort it in descending order if the sum( first index value, last index value) is even.
/// Note:
/// * don't change the given vector.
/// Examples:
/// >>> sort_array(vec![])
/// Vec::<isize>::new()
/// >>> sort_array(vec![5])
/// vec![5]
/// >>> sort_array(vec![2, 4, 3, 0, 1, 5])
/// vec![0, 1, 2, 3, 4, 5]
/// >>> sort_array(vec![2, 4, 3, 0, 1, 5, 6])
/// vec![6, 5, 4, 3, 2, 1, 0]
fn sort_array(array: Vec<isize>) -> Vec<isize> {
    if array.len() <= 1 {
        return array;
    }

    let first = array[0];
    let last = array[array.len() - 1];
    let sum = first + last;

    if sum % 2 != 0 {
        // Odd sum: sort in ascending order
        let mut sorted_array = array.clone();
        sorted_array.sort();
        sorted_array
    } else {
        // Even sum: sort in descending order
        let mut sorted_array = array.clone();
        sorted_array.sort_by(|a, b| b.cmp(a));
        sorted_array
    }
}
