/// Create a function that takes 3 numbers.
/// Returns true if one of the numbers is equal to the sum of the other two, and all numbers are integers.
/// Returns false in any other cases.
/// Examples
/// >>> any_int(5, 2, 7)
/// true
/// >>> any_int(3, 2, 2)
/// false
/// >>> any_int(3, -2, 1)
/// true
/// >>> any_int(3.6, -2.2, 2)
/// false
fn any_int(x: f64, y: f64, z: f64) -> bool {
    // Check if all numbers are integers (i.e., have no fractional part)
    let is_integer = x.fract() == 0.0 && y.fract() == 0.0 && z.fract() == 0.0;

    if !is_integer {
        return false;
    }

    // Check the three possible sum conditions
    let condition1 = x + y == z;
    let condition2 = x + z == y;
    let condition3 = y + z == x;

    condition1 || condition2 || condition3
}
