/// Given a vector of positive integers x. return a sorted vector of all 
/// elements that hasn't any even digit.
/// Note: Returned vector should be sorted in increasing order.
/// For example:
/// >>> unique_digits(vec![15, 33, 1422, 1])
/// vec![1, 15, 33]
/// >>> unique_digits(vec![152, 323, 1422, 10])
/// Vec::<isize>::new()
fn unique_digits(x: Vec<isize>) -> Vec<isize> {
    let mut result = Vec::new();

    for &num in x.iter() {
        let mut current_num = num;
        let mut has_even_digit = false;

        // Handle the case where the number is 0, although the prompt says positive integers.
        // If 0 were allowed, it has an even digit (0).
        if current_num == 0 {
            has_even_digit = true;
        } else {
            while current_num > 0 {
                let digit = (current_num % 10) as u8;
                if digit % 2 == 0 {
                    has_even_digit = true;
                    break;
                }
                current_num /= 10;
            }
        }

        if !has_even_digit {
            result.push(num);
        }
    }

    result.sort();
    result
}
