/// Write a function count_nums which takes a vector of integers and returns
/// the number of elements which has a sum of digits > 0.
/// If a number is negative, then its first signed digit will be negative:
/// e.g. -123 has signed digits -1, 2, and 3.
/// >>> count_nums(vec![])
/// 0
/// >>> count_nums(vec![-1, 11, -11])
/// 1
/// >>> count_nums(vec![1, 1, 2])
/// 3
fn count_nums(arr: Vec<isize>) -> isize {
    arr.iter().filter(|&&n| {
        let mut sum_of_digits: isize = 0;
        let mut temp_n = n;

        if temp_n == 0 {
            // Sum of digits for 0 is 0, which is not > 0
            return false;
        }

        if temp_n < 0 {
            // Handle negative numbers: first digit is negative, others are positive
            let mut first_digit = temp_n / -10;
            let mut remaining = temp_n % -10;

            // The first digit is negative
            sum_of_digits += first_digit;

            // Process the remaining digits (which are positive)
            while remaining != 0 {
                let digit = (remaining % 10) as isize;
                sum_of_digits += digit;
                remaining /= 10;
            }
        } else {
            // Handle positive numbers
            let mut temp = temp_n;
            while temp > 0 {
                let digit = temp % 10;
                sum_of_digits += digit;
                temp /= 10;
            }
        }

        sum_of_digits > 0
    }).count() as isize
}
```

