/// Task
/// We are given two strings s and c, you have to deleted all the characters in s that are equal to any character in c
/// then check if the result string is palindrome.
/// A string is called palindrome if it reads the same backward as forward.
/// You should return a tuple containing the result string and true/false for the check.
/// Example
/// >>> reverse_delete(String::from("abcde"), String::from("ae"))
/// (String::from("bcd"), false)
/// >>> reverse_delete(String::from("abcdef"), String::from("b"))
/// (String::from("acdef"), false)
/// >>> reverse_delete(String::from("abcdedcba"), String::from("ab"))
/// (String::from("cdedc"), true)
fn reverse_delete(s: String, c: String) -> (String, bool) {
    // Convert c to a set of characters for efficient lookup
    let chars_to_delete: std::collections::HashSet<char> = c.chars().collect();

    // Build the result string by filtering out characters present in c
    let result: String = s.chars()
        .filter(|&ch| !chars_to_delete.contains(&ch))
        .collect();

    // Check if the result string is a palindrome
    let is_palindrome = result.chars().eq(result.chars().rev());

    (result, is_palindrome)
}
