/// Given a vector arr of integers and a positive integer k, return a sorted vector 
/// of length k with the maximum k numbers in arr.
/// Example 1:
/// >>> maximum(vec![-3, -4, 5], 3)
/// vec![-4, -3, 5]
/// Example 2:
/// >>> maximum(vec![4, -4, 4], 2)
/// vec![4, 4]
/// Example 3:
/// >>> maximum(vec![-3, 2, 1, 2, -1, -2, 1], 1)
/// vec![2]
/// Note:
/// 1. The length of the vector will be in the range of [1, 1000].
/// 2. The elements in the vector will be in the range of [-1000, 1000].
/// 3. 0 <= k <= len(arr)
fn maximum(arr: Vec<isize>, k: isize) -> Vec<isize> {
    if k == 0 {
        return Vec::new();
    }

    // Sort the array in descending order to easily pick the largest elements.
    let mut sorted_arr = arr;
    sorted_arr.sort_unstable_by(|a, b| b.cmp(a));

    // Take the first k elements.
    let result_k = sorted_arr.into_iter().take(k as usize).collect::<Vec<isize>>();

    // The requirement is to return a *sorted* vector of length k.
    // Since we took the k largest elements, we must sort these k elements in ascending order.
