fn valid_date(date: String) -> bool {
    // Rule 1: The date string is not empty.
    if date.is_empty() {
        return false;
    }

    // Rule 4: The date should be in the format: mm-dd-yyyy
    let parts: Vec<&str> = date.split('-').collect();
    if parts.len() != 3 {
        return false;
    }

    let month_str = parts[0];
    let day_str = parts[1];
    let year_str = parts[2];

    // Check if parts are valid numbers and have correct lengths (mm, dd, yyyy)
    if month_str.len() != 2 || day_str.len() != 2 || year_str.len() != 4 {
        return false;
    }

    let month = match month_str.parse::<u32>() {
        Ok(m) => m,
        Err(_) => return false,
    };

    let day = match day_str.parse::<u32>() {
        Ok(d) => d,
        Err(_) => return false,
    };

    let year = match year_str.parse::<u32>() {
        Ok(y) => y,
        Err(_) => return false,
    };

    // Rule 3: The months should not be less than 1 or higher than 12.
    if month < 1 || month > 12 {
        return false;
    }

    // Rule 2: Check day validity based on month
    let days_in_month = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31, // Months with 31 days
        4 | 6 | 9 | 11 => 30,             // Months with 30 days
