/// You are given a vector arr of integers and you need to return
/// sum of magnitudes of integers multiplied by product of all signs
/// of each number in the vector, represented by 1, -1 or 0.
/// Note: return None for empty arr.
/// Example:
/// >>> prod_signs(vec![1, 2, 2, -4])
/// Some(9)
/// >>> prod_signs(vec![0, 1])
/// Some(0)
/// >>> prod_signs(vec![])
/// None
fn prod_signs(arr: Vec<isize>) -> Option<isize> {
    if arr.is_empty() {
        return None;
    }

    // Calculate the product of signs
    // Sign of 0 is treated as 0 for the product calculation,
    // which effectively makes the final sum 0 if any element is 0.
    let mut sign_product: isize = 1;
    let mut has_zero = false;

    for &x in arr.iter() {
        if x == 0 {
            has_zero = true;
            break; // If any element is 0, the product of signs is 0
        } else if x > 0 {
            sign_product *= 1;
        } else { // x < 0
            sign_product *= -1;
        }
    }

    if has_zero {
        return Some(0);
    }

    // Calculate the sum of magnitudes
    let sum_of_magnitudes: isize = arr.iter().map(|&x| x.abs()).sum();

    // Return the sum of magnitudes multiplied by the product of signs
    Some(sum_of_magnitudes * sign_product)
}
