/// Your task is to implement a function that will simplify the expression
/// x * n. The function returns true if x * n evaluates to a whole number and false
/// otherwise. Both x and n, are string representation of a fraction, and have the following format,
/// <numerator>/<denominator> where both numerator and denominator are positive whole numbers.
/// You can assume that x, and n are valid fractions, and do not have zero as denominator.
/// >>> simplify(String::from("1/5"), String::from("5/1"))
/// true
/// >>> simplify(String::from("1/6"), String::from("2/1"))
/// false
/// >>> simplify(String::from("7/10"), String::from("10/2"))
/// false
fn simplify(x: String, n: String) -> bool {
    // Parse x: num_x / den_x
    let parts_x: Vec<&str> = x.split('/').collect();
    let num_x: u64 = parts_x[0].parse().unwrap();
    let den_x: u64 = parts_x[1].parse().unwrap();

    // Parse n: num_n / den_n
    let parts_n: Vec<&str> = n.split('/').collect();
    let num_n: u64 = parts_n[0].parse().unwrap();
    let den_n: u64 = parts_n[1].parse().unwrap();

    // The product is (num_x / den_x) * (num_n / den_n) = (num_x * num_n) / (den_x * den_n)
    // For the result to be a whole number, the numerator must be divisible by the denominator.
    // (num_x * num_n) % (den_x * den_n) == 0

    // To prevent potential overflow during multiplication, we can simplify the fraction first,
    // but since the problem constraints aren't given, we'll stick to the direct calculation
    // and rely on u64 being large enough for typical test cases.
    // If overflow were a concern, we would use BigInt or simplify by GCD first.

    let numerator_product = num_x.checked_mul(num_n);
    let denominator_product = den_x.checked_mul(den_n);

    match (numerator_product, denominator_product) {
        (Some(num), Some(den)) => num % den == 0,
        _ => false, // Should not happen given positive whole numbers input
    }
}
