//For a given array of input numbers, calculate Mean Absolute Deviation
// around the mean of this dataset.
// Mean Absolute Deviation is the average absolute difference between each
// element and a centerpoint (mean in this case):
// MAD = average | x - x_mean |
// >>> mean_absolute_deviation([1.0, 2.0, 3.0, 4.0])
// 1.0
function mean_absolute_deviation(numbers: number[]): number {
    if (numbers.length === 0) {
        return 0;
    }

    // 1. Calculate the mean (average)
    const sum = numbers.reduce((acc, val) => acc + val, 0);
    const mean = sum / numbers.length;

    // 2. Calculate the sum of absolute differences from the mean
    const absoluteDifferencesSum = numbers.reduce((acc, val) => {
        return acc + Math.abs(val - mean);
    }, 0);

    // 3. Calculate the Mean Absolute Deviation (average of the absolute differences)
    const mad = absoluteDifferencesSum / numbers.length;

    return mad;
}
