//triples_sum_to_zero takes an array of integers as an input.
// it returns true if there are three distinct elements in the array that
// sum to zero, and false otherwise.
// >>> triples_sum_to_zero([1, 3, 5, 0])
// false
// >>> triples_sum_to_zero([1, 3, -2, 1])
// true
// >>> triples_sum_to_zero([1, 2, 3, 7])
// false
// >>> triples_sum_to_zero([2, 4, -5, 3, 9, 7])
// true
// >>> triples_sum_to_zero([1])
// false
function triples_sum_to_zero(l: number[]): boolean {
    const n = l.length;
    if (n < 3) {
        return false;
    }

    // Sort the array to use the two-pointer technique
    const sortedL = [...l].sort((a, b) => a - b);

    for (let i = 0; i < n - 2; i++) {
        let left = i + 1;
        let right = n - 1;

        while (left < right) {
            const sum = sortedL[i] + sortedL[left] + sortedL[right];

            if (sum === 0) {
                // Found three distinct elements that sum to zero
                return true;
            } else if (sum < 0) {
                // Sum is too small, need a larger value from the left
                left++;
            } else {
                // Sum is too large, need a smaller value from the right
                right--;
            }
        }
    }

    return false;
}
