/**
 * Given an array representing a branch of a tree that has non-negative integer nodes
 * your task is to pluck one of the nodes and return it.
 * The plucked node should be the node with the smallest even value.
 * If multiple nodes with the same smallest even value are found return the node that has smallest index.
 * The plucked node should be returned in an array, [ smalest_value, its index ],
 * If there are no even values or the given array is empty, return [].
 * @param arr The array of non-negative integer nodes.
 * @returns An array [smallest_even_value, index] or [] if no even values exist or the array is empty.
 */
function pluck(arr: number[]): number[] {
    if (!arr || arr.length === 0) {
        return [];
    }

    let smallestEvenValue = Infinity;
    let smallestEvenIndex = -1;

    for (let i = 0; i < arr.length; i++) {
        const value = arr[i];

        // Check if the value is even
        if (value % 2 === 0) {
            // Check if this even value is smaller than the current smallest even value found
            if (value < smallestEvenValue) {
                smallestEvenValue = value;
                smallestEvenIndex = i;
            } 
            // If the value is equal to the current smallest even value, we do nothing
            // because the current smallestEvenIndex already holds the smallest index found so far.
            // The requirement is: "If multiple nodes with the same smallest even value are found return the node that has smallest index."
            // Since we iterate from index 0 upwards, the first one we find for a given smallestEvenValue will have the smallest index.
        }
    }

    if (smallestEvenIndex === -1) {
        // No even values were found
        return [];
    }

    return [smallestEvenValue, smallestEvenIndex];
}
