//Write a function that returns true if the object q will fly, and false otherwise.
// The object q will fly if it's balanced (it is a palindromic array) and the sum of its elements is less than or equal the maximum possible weight w.
// Example:
// >>> will_it_fly([1, 2], 5)
// false
// # 1+2 is less than the maximum possible weight, but it's unbalanced.
// >>> will_it_fly([3, 2, 3], 1)
// false
// # it's balanced, but 3+2+3 is more than the maximum possible weight.
// >>> will_it_fly([3, 2, 3], 9)
// true
// # 3+2+3 is less than the maximum possible weight, and it's balanced.
// >>> will_it_fly([3], 5)
// true
// # 3 is less than the maximum possible weight, and it's balanced.
function will_it_fly(q: number[], w: number): boolean {
    // Check if the array is a palindrome (balanced)
    const isBalanced = q.length === 0 || q.reverse().every((val, index) => val === q[q.length - 1 - index]);

    // Calculate the sum of elements
    const sum = q.reduce((acc, current) => acc + current, 0);

    // Check if the sum is less than or equal to the maximum weight w
    const isWeightValid = sum <= w;

    // Return true only if both conditions are met
    return isBalanced && isWeightValid;
}
