    for (let i = 0; i < n; i++) {
        pile.push(currentLevel);

        if (i < n - 1) {
            if (isN_Odd) {
                // If n is odd, the next level is the next odd number.
                // Next odd number after currentLevel is currentLevel + 2.
                currentLevel += 2;
            } else {
                // If n is even, the next level is the next even number.
                // Next even number after currentLevel is currentLevel + 2.
                currentLevel += 2;
            }
        }
    }

