            // Extract the remaining digits
            let remainingNum = Math.abs(num) % Math.pow(10, Math.floor(Math.log10(Math.abs(num))));
            while (remainingNum > 0) {
                sumOfDigits += remainingNum % 10;
                remainingNum = Math.floor(remainingNum / 10);
