 * Both x and n are string representations of a fraction, and have the following format,
 * <numerator>/<denominator> where both numerator and denominator are positive whole numbers.
 * You can assume that x and n are valid fractions, and do not have zero as denominator.
 * 
 * @param x The first fraction as a string.
 * @param n The second fraction as a string.
 * @returns True if x * n is a whole number, false otherwise.
 */
function simplify(x: string, n: string): boolean {
    // Parse fraction x: numX / denX
    const [numXStr, denXStr] = x.split('/');
    const numX = parseInt(numXStr, 10);
    const denX = parseInt(denXStr, 10);

    // Parse fraction n: numN / denN
    const [numNStr, denNStr] = n.split('/');
    const numN = parseInt(numNStr, 10);
    const denN = parseInt(denNStr, 10);

    // The product of two fractions is: (numX / denX) * (numN / denN) = (numX * numN) / (denX * denN)
    const productNumerator = numX * numN;
    const productDenominator = denX * denN;

