    // We check if (numX * numN) % (denX * denN) === 0.
    // Since we are dealing with potentially large numbers, we can simplify the fraction first
    // by dividing the numerator and denominator by their GCD.

    const commonDivisor = gcd(productNumerator, productDenominator);

    const simplifiedNumerator = productNumerator / commonDivisor;
    const simplifiedDenominator = productDenominator / commonDivisor;

    // If the simplified denominator is 1, the result is a whole number.
    return simplifiedDenominator === 1;
