/**
 * Check if in given array of numbers, are any two numbers closer to each other than
 * given threshold.
 * 
 * @param numbers The array of numbers to check.
 * @param threshold The maximum allowed distance between two numbers.
 * @returns True if any two numbers are closer than the threshold, false otherwise.
 */
function has_close_elements(numbers: number[], threshold: number): boolean {
    if (numbers.length < 2) {
        return false;
    }

    // Sort the array first. If any two elements are closer than the threshold,
    // they must be adjacent in the sorted array.
    const sortedNumbers = [...numbers].sort((a, b) => a - b);

    for (let i = 0; i < sortedNumbers.length - 1; i++) {
        const difference = Math.abs(sortedNumbers[i + 1] - sortedNumbers[i]);
        if (difference < threshold) {
            return true;
        }
    }

    return false;
}
