/**
 * Calculates the mean of an array of numbers.
 * @param numbers The array of numbers.
 * @returns The mean of the numbers.
 */
function calculateMean(numbers: number[]): number {
    if (numbers.length === 0) {
        return 0;
    }
    const sum = numbers.reduce((acc, val) => acc + val, 0);
    return sum / numbers.length;
}

/**
 * For a given array of input numbers, calculate Mean Absolute Deviation
 * around the mean of this dataset.
 * Mean Absolute Deviation is the average absolute difference between each
 * element and a centerpoint (mean in this case):
 * MAD = average | x - x_mean |
 * @param numbers The array of input numbers.
 * @returns The Mean Absolute Deviation.
 */
function mean_absolute_deviation(numbers: number[]): number {
    if (numbers.length === 0) {
        return 0;
    }

    const mean = calculateMean(numbers);

    const absoluteDifferences = numbers.map(x => Math.abs(x - mean));

    const sumOfAbsoluteDifferences = absoluteDifferences.reduce((acc, val) => acc + val, 0);

    return sumOfAbsoluteDifferences / numbers.length;
}
