function longest(strings: string[]): string | undefined {
    if (strings.length === 0) {
        return undefined;
    }

    let longestString = strings[0];

    for (let i = 1; i < strings.length; i++) {
        const currentString = strings[i];
        // If the current string is strictly longer than the current longest string, update it.
        // This naturally handles the tie-breaking rule (return the first one) because we only update
        // if the length is strictly greater.
        if (currentString.length > longestString.length) {
            longestString = currentString;
        }
    }

    return longestString;
}
