/**
 * From a supplied array of numbers (of length at least two) select and return two that are the closest to each
 * other and return them in order (smaller number, larger number).
 * @param numbers An array of numbers with at least two elements.
 * @returns A tuple containing the two closest numbers, sorted (smaller, larger).
 */
function find_closest_elements(numbers: number[]): [number, number] {
    if (numbers.length < 2) {
        throw new Error("Input array must contain at least two elements.");
    }

    // Sort the array first. This ensures that the closest elements will be adjacent.
    const sortedNumbers = [...numbers].sort((a, b) => a - b);

    let minDifference = Infinity;
    let closestPair: [number, number] = [sortedNumbers[0], sortedNumbers[1]];

    // Iterate through the sorted array and compare adjacent elements
    for (let i = 0; i < sortedNumbers.length - 1; i++) {
        const diff = Math.abs(sortedNumbers[i + 1] - sortedNumbers[i]);

        if (diff < minDifference) {
            minDifference = diff;
            closestPair = [sortedNumbers[i], sortedNumbers[i + 1]];
        }
    }

    return closestPair;
}
