/**
 * For a given number n, find the largest number that divides n evenly, smaller than n.
 * @param n The number to find the largest divisor for.
 * @returns The largest divisor of n that is smaller than n.
 */
function largest_divisor(n: number): number {
    if (n <= 1) {
        // By definition, for n=1, there is no divisor smaller than n other than 1 itself,
        // but typically for this problem, n > 1 is assumed. Returning 1 or throwing an error
        // might be appropriate depending on strict requirements. Assuming n > 1 based on examples.
        return 1; 
    }

    // The largest divisor smaller than n is equivalent to n divided by its smallest prime factor.
    // We iterate from 2 up to the square root of n to find the smallest factor.
    for (let i = 2; i * i <= n; i++) {
        if (n % i === 0) {
            // i is the smallest factor found so far. n/i is the largest factor.
            return n / i;
        }
    }

    // If no factor is found up to sqrt(n), n must be prime.
    // The largest divisor of a prime number n (smaller than n) is 1.
    return 1;
}
