    let count = 0;

    for (let i = 1; i < n; i++) {
        // Check if the number is divisible by 11 or 13
        if (i % 11 === 0 || i % 13 === 0) {
            // Convert the number to a string to count the digit '7'
            const s = i.toString();
            for (const char of s) {
                if (char === '7') {
                    count++;
                }
            }
        }
    }

    return count;
}
