/**
 * Change numerical base of input number x to base.
 * return string representation after the conversion.
 * base numbers are less than 10.
 * @param x The number to convert.
 * @param base The target base (2 to 9).
 * @returns The string representation of x in the target base.
 */
function change_base(x: number, base: number): string {
    if (x === 0) {
        return "0";
    }

    let result = "";
    let currentX = x;

    while (currentX > 0) {
        const remainder = currentX % base;
        // Since base < 10, the remainder will always be a digit 0-9
        result = remainder.toString() + result;
        currentX = Math.floor(currentX / base);
    }

    return result;
}
