/**
 * Checks if a string of brackets is correctly balanced.
 * @param brackets A string consisting of "<" (opening) and ">" (closing) brackets.
 * @returns true if every opening bracket has a corresponding closing bracket, false otherwise.
 */
function correct_bracketing(brackets: string): boolean {
    let balance = 0;
    for (const char of brackets) {
        if (char === '<') {
            balance++;
        } else if (char === '>') {
            balance--;
        }
        // If balance drops below zero, it means a closing bracket appeared without a corresponding opening bracket.
        if (balance < 0) {
            return false;
        }
    }
    // For the brackets to be correct, the final balance must be zero.
    return balance === 0;
}
