function vowels_count(s: string): number {
    let count = 0;
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    const lowerS = s.toLowerCase();
    const len = lowerS.length;

    for (let i = 0; i < len; i++) {
        const char = lowerS[i];

        // Check for standard vowels
        if (vowels.has(char)) {
            count++;
            continue;
        }

        // Check for 'y' as a vowel only if it is at the end of the word
        if (char === 'y' && i === len - 1) {
            count++;
        }
    }
    return count;
}
