/**
 * Checks if an object q will fly based on two conditions:
 * 1. It must be balanced (a palindromic array).
 * 2. The sum of its elements must be less than or equal to the maximum possible weight w.
 *
 * @param q The array of numbers representing the object.
 * @param w The maximum possible weight.
 * @returns True if both conditions are met, false otherwise.
 */
function will_it_fly(q: number[], w: number): boolean {
    // Condition 1: Check if the array is a palindrome (balanced)
    const isBalanced = q.length === 0 || q.length === 1 || q.every((val, index) => val === q[q.length - 1 - index]);

    if (!isBalanced) {
        return false;
    }

    // Condition 2: Check if the sum of elements is less than or equal to w
    const sum = q.reduce((acc, val) => acc + val, 0);
    const isWeightValid = sum <= w;

    return isWeightValid;
}
