```typescript
/**
 * Checks if a number x is a simple power of n, meaning x = n^int for some integer int.
 *
 * @param x The number to check.
 * @param n The base.
 * @returns True if x is a simple power of n, false otherwise.
 */
function is_simple_power(x: number, n: number): boolean {
    // Handle edge cases based on the definition x = n^int

    // Case 1: n = 1
    // If n=1, n^int is always 1 for any integer int.
    if (n === 1) {
        return x === 1;
    }

    // Case 2: n = 0
    // 0^0 is often defined as 1. 0^positive = 0. 0^negative is undefined.
    if (n === 0) {
        if (x === 1) return true; // 0^0 = 1 (assuming int=0)
        if (x === 0) return true; // 0^1 = 0 (assuming int=1)
        return false;
    }

    // Case 3: x = 1
    // x = n^0 = 1 for any n != 0.
    if (x === 1) {
        return true;
    }

    // Case 4: n = -1
    // (-1)^int is 1 if int is even, and -1 if int is odd.
    if (n === -1) {
        return x === 1 || x === -1;
    }

    // Case 5: n = -2, x = 4. (-2)^2 = 4.
    // We iterate through possible integer powers of n until we reach or exceed x.
    // We start with power 1 (since x=1 is handled above).
    let power = n;
    let int = 1;

    // We use Math.abs(x) for the loop condition to handle negative x values
    // if n is negative, but we must check the sign of the calculated power against x.
    while (Math.abs(power) <= Math.abs(x)) {
        if (power === x) {
            return true;
        }

        // Check for potential overflow before multiplication, though standard JS numbers handle large ranges.
        // If power * n exceeds the safe integer limit, we stop.
        if (Math.abs(power) > Number.MAX_SAFE_INTEGER / Math.abs(n)) {
            break;
        }

        power *= n;
        int++;
    }

    return false;
}
```

