/**
 * Checks if a string is "hapts".
 * A string is hapts if its length is at least 3 and every 3 consecutive letters are distinct.
 * 
 * @param s The input string.
 * @returns True if the string is hapts, false otherwise.
 */
function is_happy(s: string): boolean {
    // Condition 1: Length must be at least 3
    if (s.length < 3) {
        return false;
    }

    // Condition 2: Every 3 consecutive letters must be distinct
    for (let i = 0; i <= s.length - 3; i++) {
        const triplet = s.substring(i, i + 3);
        const chars = new Set(triplet.split(''));

        // If the size of the set is less than 3, it means there are duplicate characters in the triplet
        if (chars.size < 3) {
            return false;
        }
    }

    return true;
}
