/**
 * Checks if one of the three numbers is equal to the sum of the other two,
 * and if all three numbers are integers.
 *
 * @param x The first number.
 * @param y The second number.
 * @param z The third number.
 * @returns True if the condition is met, false otherwise.
 */
function any_int(x: number, y: number, z: number): boolean {
    // Check if all numbers are integers
    const isInteger = (n: number): boolean => Number.isInteger(n);
    if (!isInteger(x) || !isInteger(y) || !isInteger(z)) {
        return false;
    }

    // Check if one number equals the sum of the other two
    const conditionMet = (x + y === z) || (x + z === y) || (y + z === x);

    return conditionMet;
}
