 * count_up_to(11) -> [2, 3, 5, 7] (Primes < 11)
 * It appears the function should return all prime numbers strictly less than n.
 * 
 * @param n The upper bound (exclusive).
 * @returns An array of prime numbers less than n.
 */
function count_up_to(n: number): number[] {
    if (n <= 2) {
        return [];
    }

    const primes: number[] = [];
    for (let i = 2; i < n; i++) {
        if (isPrime(i)) {
            primes.push(i);
        }
    }
    return primes;
}
