/**
 * Given a positive integer n, you have to make a pile of n levels of stones.
 * The first level has n stones.
 * The number of stones in the next level is:
 * - the next odd number if n is odd.
 * - the next even number if n is even.
 * Return the number of stones in each level in an array, where element at index
 * i represents the number of stones in the level (i+1).
 * Examples:
 * >>> make_a_pile(3)
 * [3, 5, 7]
 */
function make_a_pile(n: number): number[] {
    const pile: number[] = [];
    let currentLevel = n;

    for (let i = 0; i < n; i++) {
        pile.push(currentLevel);

        if (i < n - 1) {
            if (n % 2 !== 0) {
                // n is odd, next level is the next odd number
                currentLevel += 2;
            } else {
                // n is even, next level is the next even number
                currentLevel += 2;
            }
        }
    }

    return pile;
}
