/**
 * Given an array of positive integers x, return a sorted array of all 
 * elements that haven't any even digit.
 * Note: Returned array should be sorted in increasing order.
 * For example:
 * >>> unique_digits([15, 33, 1422, 1])
 * [1, 15, 33]
 * >>> unique_digits([152, 323, 1422, 10])
 * []
 */
function unique_digits(x: number[]): number[] {
    const hasEvenDigit = (n: number): boolean => {
        const s = String(n);
        for (let i = 0; i < s.length; i++) {
            const digit = parseInt(s[i]);
            if (digit % 2 === 0) {
                return true;
            }
        }
        return false;
    };

    const result = x
        .filter(n => !hasEvenDigit(n))
        .sort((a, b) => a - b);

    return result;
}
