            const digits = numStr.substring(1).split('');
            const firstDigit = parseInt(digits[0], 10);
            currentSum += -firstDigit;

            for (let i = 1; i < digits.length; i++) {
                currentSum += parseInt(digits[i], 10);
            }
        } else {
            // Positive number: all digits are positive.
            for (let i = 0; i < numStr.length; i++) {
                currentSum += parseInt(numStr[i], 10);
            }
        }

        if (currentSum > 0) {
            count++;
        }
    }

    return count;
}
