/**
 * Deletes all characters in string s that are present in string c,
 * and then checks if the resulting string is a palindrome.
 *
 * @param s The original string.
 * @param c The string containing characters to delete from s.
 * @returns An array containing the resulting string and a boolean indicating if it is a palindrome.
 */
function reverse_delete(s: string, c: string): [string, boolean] {
    // Create a set of characters to delete for efficient lookup
    const charsToDelete = new Set(c.split(''));

    // Build the result string by filtering out characters present in charsToDelete
    let result = '';
    for (const char of s) {
        if (!charsToDelete.has(char)) {
            result += char;
        }
    }

    // Check if the result is a palindrome
    let isPalindrome = true;
    let left = 0;
    let right = result.length - 1;

    while (left < right) {
        if (result[left] !== result[right]) {
            isPalindrome = false;
            break;
        }
        left++;
        right--;
    }

    return [result, isPalindrome];
}
