/**
 * Given an array arr of integers and a positive integer k, return a sorted array 
 * of length k with the maximum k numbers in arr.
 * 
 * @param arr The input array of integers.
 * @param k The number of maximum elements to return.
 * @returns A sorted array containing the k largest elements from arr.
 */
function maximum(arr: number[], k: number): number[] {
    if (k === 0) {
        return [];
    }

    // Sort the array in descending order
    // (b - a) ensures descending order: larger numbers come first
    const sortedArr = [...arr].sort((a, b) => b - a);

    // Take the first k elements
    const result = sortedArr.slice(0, k);

    // The requirement is to return a *sorted* array of length k.
    // Since we took the k largest elements, we must sort these k elements in ascending order.
    return result.sort((a, b) => a - b);
}
