/**
 * Validates a given date string based on specific rules.
 * The date must be in "mm-dd-yyyy" format and adhere to month/day constraints.
 *
 * @param date The date string to validate.
 * @returns true if the date is valid, false otherwise.
 */
function valid_date(date: string): boolean {
    // Rule 1: The date string is not empty.
    if (!date) {
        return false;
    }

    // Rule 4: The date should be in the format: mm-dd-yyyy
    const regex = /^(\d{2})-(\d{2})-(\d{4})$/;
    const match = date.match(regex);

    if (!match) {
        return false;
    }

    // Extract parts (Note: match[0] is the full string, match[1] is mm, match[2] is dd, match[3] is yyyy)
    const monthStr = match[1];
    const dayStr = match[2];
    const yearStr = match[3];

    const month = parseInt(monthStr, 10);
    const day = parseInt(dayStr, 10);
    const year = parseInt(yearStr, 10);

    // Rule 3: The months should not be less than 1 or higher than 12.
    if (month < 1 || month > 12) {
        return false;
    }

    // Rule 2: Check day constraints based on month
    let maxDays: number;

    // Months with 31 days: 1, 3, 5, 7, 8, 10, 12
    if ([1, 3, 5, 7, 8, 10, 12].includes(month)) {
        maxDays = 31;
    }
    // Months with 30 days: 4, 6, 9, 11
    else if ([4, 6, 9, 11].includes(month)) {
        maxDays = 30;
    }
    // February (Month 2)
    else if (month === 2) {
        // Check for leap year: divisible by 4, unless divisible by 100 but not by 400
        const isLeap = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
        maxDays = isLeap ? 29 : 28;
    } else {
        // Should not happen if Rule 3 is checked, but as a safeguard
        return false;
    }

    // Check if the day is within the valid range [1, maxDays]
    if (day < 1 || day > maxDays) {
        return false;
    }

    // If all checks pass
    return true;
}
