            signProduct *= -1;
        }
        // If num > 0, signProduct remains unchanged (multiplied by 1)
    }

    // 2. Calculate the sum of magnitudes
    const sumOfMagnitudes = arr.reduce((sum, num) => sum + Math.abs(num), 0);

    // 3. Return the product of the sum of magnitudes and the product of signs
    // Note: If signProduct is 0 (because an element was 0), the result is 0.
    return sumOfMagnitudes * signProduct;
}
