            // Update maxDepth whenever we encounter an opening bracket
            if (balance > maxDepth) {
                maxDepth = balance;
            }
        } else if (char === ']') {
            balance--;
        }

        // If balance drops below zero, the string is invalid from the start,
        // but we are looking for a *subsequence* that is nested.
        // However, the examples suggest we are checking the structure of the input string itself
        // or if a valid nested structure can be formed within it.

        // If the string is not balanced at the end, or if it becomes unbalanced mid-string,
        // it might not form a single valid structure, but the definition of "subsequence"
        // is key.

        // A simpler interpretation based on the examples:
        // 1. The string must be able to form at least one valid bracket sequence.
        // 2. That valid sequence must have a nesting depth greater than 1.

        // Let's check for overall validity first.
    }

    // If the final balance is not 0, it cannot form a complete valid sequence.
    if (balance !== 0) {
        return false;
    }

    // If the balance ever dropped below zero during iteration, it's invalid.
    // We need to re-iterate or track this during the first pass.
    balance = 0;
    for (const char of string) {
        if (char === '[') {
            balance++;
        } else if (char === ']') {
            balance--;
        }
        if (balance < 0) {
            return false; // Invalid structure
        }
    }

    // If the structure is valid (balance == 0 and never < 0), we check the max depth achieved.
    // Nesting requires a depth of at least 2 (e.g., [[]] has depth 2).
    // Depth 1 corresponds to "[]" or "[] []".
    // Depth 2 corresponds to "[[]]" or "[][]". Wait, [][] is depth 1 if we consider sequential pairs.

    // Let's re-examine the examples based on depth:
    // "[]" -> Depth 1. Expected: false.
    // "[[]]" -> Depth 2. Expected: true.
    // "[][]" -> Depth 1 (sequential). Expected: false.
    // "[][][]" -> Depth 1. Expected: false.
    // "[[]][[ " -> This example is tricky. If it implies the whole string must be valid, it fails.
    // If it implies a subsequence, "[[]]" is a subsequence, which is nested.

    // Given the examples, the function seems to check if the *entire* string forms a valid sequence
    // AND if that sequence has a nesting depth > 1.

    // Let's re-run the depth calculation assuming the string must be valid.
    let currentDepth = 0;
    let maxAchievedDepth = 0;
    for (const char of string) {
        if (char === '[') {
            currentDepth++;
            if (currentDepth > maxAchievedDepth) {
                maxAchievedDepth = currentDepth;
            }
        } else if (char === ']') {
            currentDepth--;
        }
    }

    // If the string is valid (currentDepth == 0 at end) AND max depth > 1, it is nested.
    return currentDepth === 0 && maxAchievedDepth > 1;
