function largest_smallest_integers(lst: number[]): [number | undefined, number | undefined] {
    const negatives = lst.filter(n => n < 0);
    const positives = lst.filter(n => n > 0);

    // 'a' is the largest of negative integers
    // If negatives is empty, a is undefined. Otherwise, it's the max of the negative numbers.
    const a = negatives.length > 0 ? Math.max(...negatives) : undefined;

    // 'b' is the smallest of positive integers
    // If positives is empty, b is undefined. Otherwise, it's the min of the positive numbers.
    const b = positives.length > 0 ? Math.min(...positives) : undefined;

    return [a, b];
}
