/**
 * Simplifies the expression x * n. The function returns true if x * n evaluates to a whole number and false otherwise.
 * Both x and n are string representations of a fraction, and have the following format,
 * <numerator>/<denominator> where both numerator and denominator are positive whole numbers.
 * You can assume that x, and n are valid fractions, and do not have zero as denominator.
 * 
 * @param x The first fraction as a string.
 * @param n The second fraction as a string.
 * @returns True if x * n is a whole number, false otherwise.
 */
function simplify(x: string, n: string): boolean {
    // Parse fraction x: a/b
    const [xNumStr, xDenStr] = x.split('/');
    const xNum = parseInt(xNumStr, 10);
    const xDen = parseInt(xDenStr, 10);

    // Parse fraction n: c/d
    const [nNumStr, nDenStr] = n.split('/');
    const nNum = parseInt(nNumStr, 10);
    const nDen = parseInt(nDenStr, 10);

    // Multiplication of fractions: (a/b) * (c/d) = (a*c) / (b*d)
    const resultNumerator = xNum * nNum;
    const resultDenominator = xDen * nDen;

    // The result is a whole number if the numerator is perfectly divisible by the denominator.
    // Since all inputs are positive whole numbers, the result will be non-negative.
    return resultNumerator % resultDenominator === 0;
}
