/**
 * Determines how far off each guess was compared to the actual score.
 * If the guess is correct, the difference is 0. Otherwise, it's the absolute difference.
 * 
 * @param game An array of actual scores.
 * @param guess An array of guesses.
 * @returns An array of the same length denoting the difference for each match.
 */
function compare(game: number[], guess: number[]): number[] {
    if (game.length !== guess.length) {
        throw new Error("Input arrays must be of equal length.");
    }

    return game.map((score, index) => {
        const guessedValue = guess[index];
        return Math.abs(score - guessedValue);
    });
}
