/**
 * Given a positive integer, obtain its roman numeral equivalent as a string,
 * and return it in lowercase.
 * Restrictions: 1 <= num <= 1000
 * Examples:
 * >>> int_to_mini_roman(19)
 * "xix"
 * >>> int_to_mini_roman(152)
 * "clii"
 * >>> int_to_mini_roman(426)
 * "cdxxvi"
 */
function int_to_mini_roman(number: number): string {
    const romanMap: { [key: number]: string } = {
        1000: "m",
        900: "cm",
        500: "d",
        400: "cd",
        100: "c",
        90: "xc",
        50: "l",
        40: "xl",
        10: "x",
        9: "ix",
        5: "v",
        4: "iv",
        1: "i"
    };

    let result = "";
    let remaining = number;

    // Iterate through the keys in descending order of value
    const sortedKeys = Object.keys(romanMap).map(Number).sort((a, b) => b - a);

    for (const value of sortedKeys) {
        while (remaining >= value) {
            result += romanMap[value];
            remaining -= value;
        }
    }

    return result;
}
