```typescript
/**
 * Given two arrays operator, and operand. The first array has basic algebra operations, and 
 * the second array is an array of integers. Use the two given arrays to build the algebric 
 * expression and return the evaluation of this expression.
 * The basic algebra operations:
 * Addition ( + ) 
 * Subtraction ( - ) 
 * Multiplication ( * ) 
 * Floor division ( // ) 
 * Exponentiation ( ** ) 
 * Example:
 * operator['+', '*', '-']
 * array = [2, 3, 4, 5]
 * result = 2 + 3 * 4 - 5
 * => result = 9
 * Note:
 * The length of operator array is equal to the length of operand array minus one.
 * Operand is an array of of non-negative integers.
 * Operator array has at least one operator, and operand array has at least two operands.
 */
function do_algebra(operator: string[], operand: number[]): number {
    // We need to evaluate the expression respecting standard order of operations (PEMDAS/BODMAS).
    // Since the input format is infix notation without parentheses, we must implement
    // an expression evaluator that handles operator precedence.

    // Precedence:
    // 1. Exponentiation (**) - Right to left
    // 2. Multiplication (*) and Floor Division (//) - Left to right
    // 3. Addition (+) and Subtraction (-) - Left to right

    // Helper function to apply an operation
    const applyOp = (a: number, b: number, op: string): number => {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '*': return a * b;
            case '//': return Math.floor(a / b);
            case '**': return Math.pow(a, b);
            default: throw new Error(`Unknown operator: ${op}`);
        }
    };

    // Shunting-yard algorithm or direct evaluation using two stacks (values and operators)
    // is the standard way to handle precedence.

    const values: number[] = [operand[0]];
    const ops: string[] = [];

    const precedence = (op: string): number => {
        if (op === '+' || op === '-') return 1;
        if (op === '*' || op === '/') return 2; // Note: We treat // as division for precedence logic
        if (op === '**') return 3;
        return 0;
    };

    const processOperation = () => {
        const op = ops.pop()!;
        const b = values.pop()!;
        const a = values.pop()!;
        values.push(applyOp(a, b, op));
    };

    for (let i = 0; i < operator.length; i++) {
        const currentOp = operator[i];
        const nextOperand = operand[i + 1];

        // Handle right-associativity for exponentiation (**)
        if (currentOp === '**') {
            while (ops.length > 0 && precedence(ops[ops.length - 1]) > precedence(currentOp)) {
                processOperation();
            }
            ops.push(currentOp);
        } else {
            // Standard left-to-right associativity for others
            while (ops.length > 0 && precedence(ops[ops.length - 1]) >= precedence(currentOp)) {
                processOperation();
            }
            ops.push(currentOp);
        }

        // Push the next operand
        values.push(nextOperand);
    }

    // Process remaining operations
    while (ops.length > 0) {
        processOperation();
    }

    return values[0];
}
